# === CACHE MANAGER SERVICE ===
class GeminiCacheManager:
    """
    Manages Gemini context caching to optimize token usage and performance.
    This manager creates a single, combined cache per user that includes all
    relevant context (user info, settings, diary, etc.).
    """
    def __init__(self, ttl_hours: int = 4):
        # Firestore collection path for cache metadata
        self.CACHE_COLLECTION = "system/cache_manager/user_caches"
        
        # Initialize Firestore client for persistent cache tracking
        self.db = firestore.Client()
        
        self.ttl_seconds = ttl_hours * 3600
        self.local_validation_ttl_seconds = 60
        self._validated_cache_refs: Dict[str, Dict[str, Any]] = {}
        logging.info(f"✅ Cache Manager initialized with Firestore persistence and {ttl_hours}-hour TTL.")

    def _get_user_key(self, account_id: str, aac_user_id: str) -> str:
        """Generates a unique key for a user to manage their cache."""
        # Versioned to invalidate stale cached base context after diary context moved to DELTA.
        # v3: model upgraded from gemini-1.5-flash-latest to gemini-2.0-flash (caches are model-specific)
        return f"v3_{account_id}_{aac_user_id}"
    
    async def _load_cache_from_firestore(self, user_key: str) -> Optional[Dict]:
        """Load cache info from Firestore."""
        try:
            doc_ref = self.db.collection(self.CACHE_COLLECTION).document(user_key)
            doc = await asyncio.to_thread(doc_ref.get)
            
            if doc.exists:
                return doc.to_dict()
            return None
        except Exception as e:
            logging.error(f"Error loading cache from Firestore for {user_key}: {e}")
            return None
    
    async def _save_cache_to_firestore(
        self,
        user_key: str,
        cache_name: str,
        created_at: float,
        message_count: int = 0,
        chat_history_cached: bool = True,
        consent_fingerprint: str = "",
    ):
        """Save cache info to Firestore with enough metadata to decide if drift checks apply."""
        try:
            expires_at = created_at + self.ttl_seconds
            doc_ref = self.db.collection(self.CACHE_COLLECTION).document(user_key)

            await asyncio.to_thread(
                doc_ref.set,
                {
                    "user_key": user_key,
                    "cache_name": cache_name,
                    "created_at": created_at,
                    "expires_at": expires_at,
                    "ttl_seconds": self.ttl_seconds,
                    "message_count": message_count,
                    "chat_history_cached": bool(chat_history_cached),
                    "consent_fingerprint": consent_fingerprint,
                }
            )
            logging.info(
                f"💾 Saved cache reference to Firestore: {user_key} -> {cache_name} "
                f"({message_count} messages, chat_history_cached={bool(chat_history_cached)})"
            )
            self._validated_cache_refs[user_key] = {
                "cache_name": cache_name,
                "expires_at": expires_at,
                "validated_at": dt.now().timestamp(),
            }
        except Exception as e:
            logging.error(f"Error saving cache to Firestore for {user_key}: {e}")
    
    async def _delete_cache_from_firestore(self, user_key: str):
        """Delete cache info from Firestore."""
        try:
            doc_ref = self.db.collection(self.CACHE_COLLECTION).document(user_key)
            await asyncio.to_thread(doc_ref.delete)
            self._validated_cache_refs.pop(user_key, None)
            logging.info(f"Deleted cache reference from Firestore: {user_key}")
        except Exception as e:
            logging.error(f"Error deleting cache from Firestore for {user_key}: {e}")

    async def _is_cache_valid(self, user_key: str) -> bool:
        """Checks if a user's cache exists in Firestore and is within its TTL."""
        now_ts = dt.now().timestamp()
        local_cache_ref = self._validated_cache_refs.get(user_key)
        if local_cache_ref:
            if (
                local_cache_ref.get('cache_name')
                and local_cache_ref.get('expires_at', 0) > now_ts
                and (now_ts - local_cache_ref.get('validated_at', 0)) <= self.local_validation_ttl_seconds
            ):
                return True
            if local_cache_ref.get('expires_at', 0) <= now_ts:
                self._validated_cache_refs.pop(user_key, None)

        print(f"DEBUG: _is_cache_valid called for {user_key}", flush=True)
        cache_data = await self._load_cache_from_firestore(user_key)
        print(f"DEBUG: cache_data from Firestore: {cache_data}", flush=True)
        
        if not cache_data:
            print(f"DEBUG: No cache_data, returning False", flush=True)
            return False
        
        created_at = cache_data.get('created_at', 0)
        is_expired = (dt.now().timestamp() - created_at) > self.ttl_seconds
        
        if is_expired:
            logging.warning(f"Cache for user '{user_key}' has expired. TTL: {self.ttl_seconds}s.")
            # Clean up expired cache from Firestore and Gemini
            await self._delete_expired_cache(user_key, cache_data.get('cache_name'))
            return False
        
        # Cache is valid - verify it still exists in Gemini
        cache_name = cache_data.get('cache_name')
        if cache_name:
            try:
                # Verify the cache still exists in Gemini API
                await _gemini_client.aio.caches.get(name=cache_name)
                self._validated_cache_refs[user_key] = {
                    "cache_name": cache_name,
                    "expires_at": cache_data.get('expires_at', now_ts + self.ttl_seconds),
                    "validated_at": now_ts,
                }
                logging.info(f"Cache for '{user_key}' is valid: {cache_name}")
                return True
            except Exception as e:
                logging.warning(f"Cache reference exists in Firestore but not in Gemini: {cache_name}. Error: {e}")
                # Clean up stale reference
                await self._delete_cache_from_firestore(user_key)
                return False
        
        return False
    
    async def _delete_expired_cache(self, user_key: str, cache_name: Optional[str]):
        """Delete expired cache from both Firestore and Gemini."""
        # Delete from Firestore
        await self._delete_cache_from_firestore(user_key)
        
        # Delete from Gemini if cache_name provided
        if cache_name:
            try:
                await _gemini_client.aio.caches.delete(name=cache_name)
                logging.info(f"Deleted expired Gemini cache: {cache_name}")
            except Exception as e:
                logging.warning(f"Error deleting expired Gemini cache {cache_name}: {e}")

    async def _build_base_context(self, account_id: str, aac_user_id: str) -> str:
        """
        Builds the BASE context for caching - contains only stable, long-term data.
        This is cached and reused across multiple requests.
        
        Includes:
        - System prompt
        - User profile narrative (stable)
        - Friends & family (stable)
        - Settings (rarely changes)
        - Birthdays (stable)
        - Old chat history (>10 messages old)
        
        Excludes (moved to delta):
        - Current mood (changes frequently)
        - Current location/people/activity (changes per request)
        - Recent chat history (last 5-10 turns)
        - User pages (frequently edited)
        """
        logging.info(f"🏛️ Building BASE context (for caching) for {account_id}/{aac_user_id}...")
        
        # Fetch only stable data for caching
        # NOTE: chat_history is LIMITED to recent messages (CHAT_HISTORY_ACTIVE_DAYS)
        # Older messages are summarized in chat_narrative to save tokens
        tasks = {
            "user_info": load_firestore_document(account_id, aac_user_id, "info/user_narrative", DEFAULT_USER_INFO),
            "settings": load_settings_from_file(account_id, aac_user_id),
            "birthdays": load_birthdays_from_file(account_id, aac_user_id),
            "chat_history": load_recent_chat_history(account_id, aac_user_id, days=CHAT_HISTORY_ACTIVE_DAYS),
            "chat_narrative": load_chat_derived_narrative(account_id, aac_user_id),
            "friends_family": load_firestore_document(account_id, aac_user_id, "info/friends_family", {"friends_family": []}),
            "consent": load_consent(account_id, aac_user_id),
        }
        results = await asyncio.gather(*tasks.values())
        context_data = dict(zip(tasks.keys(), results))

        _consent = context_data.get("consent") or {}
        _use_entered = is_personalization_enabled(_consent)
        _use_learned = is_learning_enabled(_consent)

        # System prompt providing instructions to the LLM
        system_prompt = """You are Bravo, an AI communication assistant for AAC users. Your role is to generate relevant response options based on the user's context.

IMPORTANT: Always prioritize the User Profile information as your PRIMARY source. The user's personal details, family, interests, and disability information should be the foundation of your responses. Use the current situation and recent activity as SECONDARY context to personalize responses, but never let them overshadow the core user profile.

🔊 CRITICAL SPEECH RULE: When creating summary fields for response options, NEVER include the user's personal name. The summary field is what gets spoken aloud to the user, so it should use generic language like "I am", "I feel", "I want" instead of "John is", "John feels", "John wants". Personal names should only appear in the full option text if necessary, never in summaries.

Format responses as a JSON array of objects, each with "option" and "summary" keys.
Analyze the provided context to create helpful, personalized suggestions."""

        # Assemble the BASE context string
        context_parts = [f"--- SYSTEM PROMPT ---\n{system_prompt}\n"]

        # PRIORITIZE USER PROFILE - gated on use_entered_details
        if _use_entered and context_data["user_info"]:
            user_narrative = context_data['user_info'].get('narrative', 'Not available')
            context_parts.append(f"=== PRIMARY USER PROFILE (MOST IMPORTANT) ===\n{user_narrative}\n\n⚠️  REMEMBER: This user profile should be the foundation for ALL responses. Personal details, family, interests, and characteristics mentioned here are the most important context.\n")
            overrides = normalize_ai_option_overrides(context_data["user_info"].get("aiOptionOverrides", {}))
            context_parts.append(build_ai_option_overrides_prompt_block(overrides) + "\n")

        # Additional supporting context (stable data only) — also gated on use_entered_details
        if _use_entered and context_data["friends_family"]:
            context_parts.append(f"--- Friends & Family (Supporting Context) ---\n{json.dumps(context_data['friends_family'], indent=2)}\n")
        if context_data["settings"]:
            context_parts.append(f"--- User Settings (Supporting Context) ---\n{json.dumps(context_data['settings'], indent=2)}\n")
        if _use_entered and context_data["birthdays"] and (context_data["birthdays"].get("userBirthdate") or context_data["birthdays"].get("friendsFamily")):
            context_parts.append(f"--- Birthdays (Supporting Context) ---\n{json.dumps(context_data['birthdays'], indent=2)}\n")
        
        # Vocabulary level instruction (replaces sending full pages/vocabulary lists)
        # This saves ~261k tokens by using instruction instead of full word lists
        if context_data["settings"]:
            vocabulary_level = context_data["settings"].get("vocabularyLevel", "functional")
            vocab_instruction = get_vocabulary_level_instruction(vocabulary_level)
            context_parts.append(f"--- Vocabulary Guidelines ---\n{vocab_instruction}\n")
            logging.info(f"📚 Using vocabulary level: {vocabulary_level} (instruction-based, not full pages)")
        
        # AI-extracted chat narrative (replaces old chat history to save tokens)
        if _use_learned and context_data["chat_narrative"]:
            chat_narrative = context_data["chat_narrative"]
            if (chat_narrative.get("narrative_text") or chat_narrative.get("extracted_facts")
                    or chat_narrative.get("recent_greetings") or chat_narrative.get("answered_questions")):
                chat_context_parts = ["--- User Communication Patterns (from Chat History) ---"]
                
                # Add narrative summary
                if chat_narrative.get("narrative_text"):
                    chat_context_parts.append(f"Summary: {chat_narrative['narrative_text']}")
                
                # Extracted facts — gated on learn_from_history
                if _use_learned and chat_narrative.get("extracted_facts"):
                    facts_text = []
                    for fact in chat_narrative["extracted_facts"]:
                        fact_text = fact.get("fact", "")
                        mention_count = fact.get("mention_count", 1)
                        sentiment = fact.get("sentiment", "likes")
                        direction = "Likes" if sentiment == "likes" else "Does NOT like"
                        facts_text.append(f"  • {direction}: {fact_text} (mentioned {mention_count}x)")
                    chat_context_parts.append("Extracted Facts:\n" + "\n".join(facts_text))
                
                # Add common greetings (to help avoid repetition)
                if chat_narrative.get("recent_greetings"):
                    greetings = ", ".join(chat_narrative["recent_greetings"])
                    chat_context_parts.append(f"Recent Greetings Used: {greetings}")
                    chat_context_parts.append("⚠️ Suggest DIFFERENT greeting variations to avoid repetition")
                
                # Add answered questions with better formatting for LLM comprehension
                if chat_narrative.get("answered_questions"):
                    qa_pairs = []
                    # Convert shorthand keys to natural language for better LLM understanding
                    key_mappings = {
                        "city_to_visit": "City they want to visit",
                        "favorite_music": "Favorite music",
                        "favorite_food": "Favorite food",
                        "favorite_color": "Favorite color",
                        "favorite_sport": "Favorite sport",
                        "sounds_for_talker": "Sounds they want for their AAC device",
                        "yesterday_activity": "What they did recently",
                        "favorite_kind_of_music": "Favorite kind of music",
                    }
                    
                    for q, a in chat_narrative["answered_questions"].items():
                        # Use mapped question or original if not in mapping
                        question_text = key_mappings.get(q, q.replace("_", " ").title())
                        qa_pairs.append(f"  • {question_text}: {a}")
                    
                    chat_context_parts.append("⭐ User Preferences (from past conversations):\n" + "\n".join(qa_pairs))
                    chat_context_parts.append("💡 USE THESE when generating relevant suggestions (e.g., include Savannah when suggesting vacation destinations)")
                
                context_parts.append("\n".join(chat_context_parts) + "\n")
        
        # NOTE: Recent chat history is NOW in DELTA context only (not cached)
        # This reduces cache size and costs significantly since chat changes frequently
        # Older messages are already summarized in chat_derived_narrative above
        
        base_string = "\n".join(context_parts)
        logging.info(f"✅ BASE context for {account_id}/{aac_user_id} is {len(base_string)} chars (~{len(base_string)//4} tokens) - ready for caching")
        return base_string
    
    async def _build_delta_context(
        self,
        account_id: str,
        aac_user_id: str,
        query_hint: str = "",
        compose_mode: bool = False,
        compose_body: str = "",
        prefetched_user_info: Optional[Dict[str, Any]] = None,
        prefetched_settings: Optional[Dict[str, Any]] = None,
        include_rich_context: bool = True,
    ) -> str:
        """
        Builds the DELTA context - dynamic data that changes frequently.
        This is passed as standard input text with each request (NOT cached).
        
        Includes:
        - Current mood (changes frequently)
        - Current location/people/activity (changes per request)
        - Current date and diary entries (date-sensitive; query-sensitive)
        - Recent chat history (last 10 turns)
        - User pages (frequently edited)
        """
        logging.info(f"⚡ Building DELTA context (dynamic data) for {account_id}/{aac_user_id}...")
        
        query_hint_lower = str(query_hint or "").lower()

        # Fetch dynamic data
        # NOTE: chat_history uses recent messages (CHAT_HISTORY_ACTIVE_DAYS) to match BASE context
        # NOTE: pages moved to BASE cache (they rarely change, but are huge)
        tasks = {
            "user_current": load_firestore_document(account_id, aac_user_id, "info/current_state", DEFAULT_USER_CURRENT),
            "chat_history": load_recent_chat_history(account_id, aac_user_id, days=CHAT_HISTORY_ACTIVE_DAYS),
            "consent": load_consent(account_id, aac_user_id),
        }
        if include_rich_context:
            tasks["birthdays"] = load_birthdays_from_file(account_id, aac_user_id)
            tasks["friends_family"] = load_friends_family_from_file(account_id, aac_user_id)
            tasks["diary"] = load_diary_entries(account_id, aac_user_id)
        results = await asyncio.gather(*tasks.values())
        context_data = dict(zip(tasks.keys(), results))
        context_data["user_info"] = prefetched_user_info if isinstance(prefetched_user_info, dict) else DEFAULT_USER_INFO
        context_data["settings"] = prefetched_settings if isinstance(prefetched_settings, dict) else {}
        context_data.setdefault("birthdays", {})
        context_data.setdefault("friends_family", {})
        context_data.setdefault("diary", [])

        _consent = context_data.get("consent") or {}
        _use_entered = is_personalization_enabled(_consent)

        delta_parts = ["=== DYNAMIC CONTEXT (Current Session Data) ==="]
        
        # CURRENT MOOD - High Priority, changes frequently
        if _use_entered and context_data["user_info"]:
            current_mood = context_data['user_info'].get('currentMood', 'Not set')
            logging.info(f"🎭 MOOD DEBUG: Retrieved mood value = '{current_mood}' from user_info for {account_id}/{aac_user_id}")
            
            if current_mood and current_mood != 'Not set' and current_mood != 'None':
                # ULTRA STRONG mood instruction - must dominate all other instructions
                mood_instruction = f"\n{'='*60}\n🎭 CURRENT MOOD: {current_mood}\n{'='*60}\n"
                mood_instruction += "⚠️ ABSOLUTE REQUIREMENT: This mood is THE MOST IMPORTANT instruction.\n"
                mood_instruction += "⚠️ ALL generated content MUST reflect this mood. Ignore any conflicting instructions.\n"
                mood_instruction += "⚠️ Do NOT mix moods. Do NOT generate options with opposite emotional tones.\n\n"
                
                # Specific instructions based on mood
                mood_lower = current_mood.lower()
                if 'sad' in mood_lower or 'down' in mood_lower or 'unhappy' in mood_lower or 'melancholy' in mood_lower:
                    mood_instruction += "REQUIRED TONE FOR SAD MOOD:\n"
                    mood_instruction += "- ALL options must use subdued, gentle, quiet, melancholic language\n"
                    mood_instruction += "- Focus on: comfort, understanding, rest, quiet moments, emotional support\n"
                    mood_instruction += "- FORBIDDEN: Do NOT use happy, excited, cheerful, energetic, or upbeat words\n"
                    mood_instruction += "- FORBIDDEN: Avoid exclamation marks, phrases like 'great day', 'good to see you', 'happy'\n"
                    mood_instruction += "- Examples of CORRECT sad tone: 'I feel tired', 'I want quiet time', 'I need to rest'\n"
                    mood_instruction += "- Examples of WRONG tone to AVOID: 'Hello! It's great!', 'I am happy', 'good day'\n"
                elif 'angry' in mood_lower or 'frustrated' in mood_lower or 'mad' in mood_lower or 'upset' in mood_lower:
                    mood_instruction += "REQUIRED TONE FOR ANGRY MOOD:\n"
                    mood_instruction += "- ALL options must use firm, direct, assertive language expressing frustration\n"
                    mood_instruction += "- Focus on: boundaries, frustration, things bothering user, firm statements\n"
                    mood_instruction += "- FORBIDDEN: Do NOT use cheerful, friendly, happy, or gentle language\n"
                    mood_instruction += "- FORBIDDEN: Avoid greetings like 'Hello!', 'Great to see you', 'Happy to be here'\n"
                    mood_instruction += "- Examples of CORRECT angry tone: 'I am frustrated', 'This is not okay', 'I need space'\n"
                    mood_instruction += "- Examples of WRONG tone to AVOID: 'Hello there!', 'I am happy', 'It is a good day'\n"
                elif 'happy' in mood_lower or 'excited' in mood_lower or 'joyful' in mood_lower or 'cheerful' in mood_lower:
                    mood_instruction += "REQUIRED TONE FOR HAPPY MOOD:\n"
                    mood_instruction += "- ALL options must use upbeat, positive, energetic, enthusiastic language\n"
                    mood_instruction += "- Focus on: celebration, joy, excitement, fun activities\n"
                    mood_instruction += "- FORBIDDEN: Do NOT use sad, tired, or negative expressions\n"
                elif 'silly' in mood_lower or 'playful' in mood_lower or 'funny' in mood_lower:
                    mood_instruction += "REQUIRED TONE FOR SILLY/PLAYFUL MOOD:\n"
                    mood_instruction += "- ALL options must use playful, humorous, lighthearted, whimsical language\n"
                    mood_instruction += "- Focus on: silliness, jokes, playful statements, fun wordplay\n"
                    mood_instruction += "- FORBIDDEN: Do NOT use serious, formal, or somber language\n"
                elif 'calm' in mood_lower or 'peaceful' in mood_lower or 'relaxed' in mood_lower:
                    mood_instruction += "REQUIRED TONE FOR CALM MOOD:\n"
                    mood_instruction += "- ALL options must use gentle, soothing, tranquil, peaceful language\n"
                    mood_instruction += "- Focus on: peace, contentment, quiet activities, relaxation\n"
                
                mood_instruction += f"\n{'='*60}\n"
                delta_parts.append(mood_instruction)
                logging.info(f"✅ MOOD INSTRUCTION ADDED: {current_mood} with strict requirements")
            else:
                logging.warning(f"⚠️ MOOD NOT ADDED: currentMood = '{current_mood}' (filtered out)")
        
        # Current situation - location, people, activity
        if context_data["user_current"]:
            if not compose_mode and _use_entered:
                current_parts = []
                current_parts.extend([
                    f"Location: {context_data['user_current'].get('location', 'Unknown')}",
                    f"People Present: {context_data['user_current'].get('people', 'None')}",
                    f"Activity: {context_data['user_current'].get('activity', 'Idle')}"
                ])
                delta_parts.append(f"\n📍 CURRENT SITUATION:\n{chr(10).join(current_parts)}\n")

                topic_title = (context_data["user_current"].get("topicTitle") or "").strip()
                focus_chapters = (context_data["user_current"].get("focusChapters") or "").strip()
                focus_plot_points = (context_data["user_current"].get("focusPlotPoints") or "").strip()
                topic_summary = (context_data["user_current"].get("topicSummary") or "").strip()
                discussion_narrative = topic_summary or focus_plot_points

                if topic_title or focus_chapters or discussion_narrative:
                    discussion_lines = [
                        "📚 BOOK/DISCUSSION CONTEXT (SUPPLEMENTAL)",
                        f"Topic Title: {topic_title or 'Not provided'}",
                        f"Focus Chapters: {focus_chapters or 'Not provided'}",
                        f"Discussion Narrative: {discussion_narrative or 'Not provided'}",
                        "Use this context at the SAME PRIORITY as Location, People Present, and Activity.",
                        "Only apply this context when the request is clearly about the current topic/book/discussion.",
                        "If the request is general, do not force topic-specific options.",
                        "If chapter range is provided and topic context is used, avoid introducing events beyond that range."
                    ]
                    delta_parts.append("\n" + "\n".join(discussion_lines) + "\n")
            else:
                # Compose mode: suppress location/book context, inject compose guidance instead
                compose_lines = [
                    "✏️ COMPOSE MODE — USER IS ACTIVELY WRITING A DOCUMENT",
                    "⚠️ IGNORE: Location, People Present, Activity, and Book/Discussion context — NOT relevant.",
                    "⚠️ IGNORE: Any greeting, conversational, or situational context.",
                    "FOCUS ONLY ON: Generating options that are natural next phrases, sentences, or ideas",
                    "  for the user's written composition (letter, story, message, etc.).",
                    "OPTIONS must be written document phrases — not spoken conversation starters.",
                    "Keep options concise, literary, and appropriate for written text.",
                ]
                compose_body_text = (compose_body or "").strip()
                if compose_body_text:
                    compose_lines.append(f'\nCURRENT COMPOSITION SO FAR:\n"{compose_body_text}"')
                    compose_lines.append("Continue this composition naturally. Options should logically follow what has been written.")
                delta_parts.append("\n" + "\n".join(compose_lines) + "\n")

        today_date = dt.now().date()
        current_date_str = today_date.strftime('%Y-%m-%d')
        celebrations_context = _build_upcoming_celebrations_context(
            birthday_data=context_data.get("birthdays") if _use_entered else {},
            friends_family_data=context_data.get("friends_family") if _use_entered else {},
            settings_data=context_data.get("settings") or {},
            today_date=today_date,
            days_ahead=60,
            max_items=20,
        )

        delta_parts.append(
            f"\n--- TODAY'S DATE (CRITICAL FOR DIARY CONTEXT) ---\n{current_date_str}\n"
            "⚠️ IMPORTANT: Use this date to determine if diary entries are recent (past), current (today), or future events.\n"
        )

        if _use_entered and include_rich_context and context_data["diary"]:
            def parse_diary_date(entry: Dict) -> Optional[date]:
                if not isinstance(entry, dict):
                    return None
                raw_date = entry.get("date")
                if not isinstance(raw_date, str) or not raw_date.strip():
                    return None
                raw_date = raw_date.strip()

                for fmt in ("%Y-%m-%d", "%m-%d-%Y", "%m/%d/%Y"):
                    try:
                        return dt.strptime(raw_date, fmt).date()
                    except ValueError:
                        continue

                try:
                    return dt.fromisoformat(raw_date.replace("Z", "+00:00")).date()
                except ValueError:
                    return None

            dated_entries = []
            undated_entries = []
            for entry in context_data["diary"]:
                parsed_date = parse_diary_date(entry)
                if parsed_date is None:
                    undated_entries.append(entry)
                else:
                    dated_entries.append((entry, parsed_date))

            dated_entries.sort(key=lambda item: item[1], reverse=True)

            completed_entries = [(entry, parsed) for entry, parsed in dated_entries if parsed <= today_date]
            upcoming_entries = [(entry, parsed) for entry, parsed in dated_entries if parsed > today_date]
            recent_cutoff = today_date - timedelta(days=14)
            recent_completed_entries = [
                entry for entry, parsed in completed_entries if parsed >= recent_cutoff
            ]

            recent_activity_keywords = [
                "recent activit",
                "within 14 days",
                "last 14 days",
                "what i did",
                "have done recently",
                "past activit",
            ]
            use_recent_only = any(keyword in query_hint_lower for keyword in recent_activity_keywords)

            completed_entries_for_context = recent_completed_entries if use_recent_only else [
                entry for entry, _ in completed_entries[:15]
            ]
            completed_heading = (
                f"Completed Diary Entries Within Last 14 Days Only (date >= {recent_cutoff.strftime('%Y-%m-%d')} and <= {current_date_str}, newest first, max 15):"
                if use_recent_only
                else f"Completed / Today Diary Entries (date <= {current_date_str}, newest first, max 15):"
            )
            recent_only_rule = (
                f"- THIS REQUEST is about recent past activity. Use ONLY completed diary entries from the last 14 days ({recent_cutoff.strftime('%Y-%m-%d')} through {current_date_str}).\n"
                "- DO NOT use older completed diary entries for this request, even if they seem relevant.\n"
                "- DO NOT use upcoming/future diary entries as a fallback if there are no completed entries in the last 14 days.\n"
                "- If there are no completed diary entries in the last 14 days, do not generate any activity-based options from diary data.\n"
                if use_recent_only
                else ""
            )
            upcoming_entries_for_context = [] if use_recent_only else [
                entry for entry, _ in list(reversed(upcoming_entries[-15:]))
            ]
            upcoming_heading = (
                "Upcoming Diary Entries (hidden for this recent-activity request; do not use):"
                if use_recent_only
                else f"Upcoming Diary Entries (date > {current_date_str}, soonest first, max 15):"
            )

            diary_context = f"""--- Diary Entries (Dynamic Context) ---
📅 TODAY'S DATE: {current_date_str}
⚠️ CRITICAL INSTRUCTIONS FOR DIARY INTERPRETATION:
- Entries with dates BEFORE {current_date_str} = PAST events (use past tense: "I did", "I went", "I had")
- Entries with date {current_date_str} = TODAY'S events (use present tense: "I am", "I'm doing")
- Entries with dates AFTER {current_date_str} = FUTURE events (use future tense: "I will", "I'm going to", "I have planned")

⚠️ DIARY USAGE RULES:
- For prompts about "recent activities" or "what I did", use ONLY Completed/Today entries.
{recent_only_rule}- For prompts about "upcoming plans" or "what I will do", use ONLY Upcoming entries.
- NEVER describe Upcoming entries as if they already happened.

{completed_heading}
{json.dumps(completed_entries_for_context[:15], indent=2)}

{upcoming_heading}
{json.dumps(upcoming_entries_for_context, indent=2)}

Undated Diary Entries (use cautiously, max 5):
{json.dumps(undated_entries[:5], indent=2)}
"""
            delta_parts.append(diary_context)

        # Live time context (dynamic per request; NOT cached)
        # This prevents stale/hallucinated times when users ask about current time/date.
        now_utc = dt.now(timezone.utc)
        mountain_now = now_utc.astimezone(ZoneInfo("America/Denver"))

        preferred_tz_name = "America/Denver" if (
            "mountain" in query_hint_lower or
            "mst" in query_hint_lower or
            "mdt" in query_hint_lower
        ) else "UTC"

        try:
            preferred_now = now_utc.astimezone(ZoneInfo(preferred_tz_name))
        except Exception:
            preferred_tz_name = "UTC"
            preferred_now = now_utc

        delta_parts.append(
            "\n🕒 LIVE DATE/TIME CONTEXT (AUTHORITATIVE - USE FOR TIME/DATE QUESTIONS):\n"
            f"- Current UTC: {now_utc.strftime('%Y-%m-%d %I:%M:%S %p UTC')}\n"
            f"- Current US Mountain (America/Denver): {mountain_now.strftime('%Y-%m-%d %I:%M:%S %p %Z')}\n"
            f"- Preferred timezone for this request: {preferred_tz_name}\n"
            f"- Current time in preferred timezone: {preferred_now.strftime('%Y-%m-%d %I:%M:%S %p %Z')}\n"
            "⚠️ TIME ACCURACY RULE: If the prompt asks for current time/date, use the exact values above."
            " Do NOT invent or reuse old times from prior context.\n"
        )

        celebration_keywords = [
            "greeting", "hello", "hi", "good morning", "good afternoon", "good evening",
            "plan", "plans", "upcoming", "going on", "birthday", "holiday", "celebrate", "celebration"
        ]
        if _use_entered and include_rich_context and any(keyword in query_hint_lower for keyword in celebration_keywords):
            celebrations_context += (
                "\n⚠️ HIGH PRIORITY FOR THIS REQUEST: The prompt indicates greetings/plans/celebrations. "
                "Prefer options that reference relevant upcoming birthdays/holidays naturally and in first person."
            )
            celebrations_context += (
                "\n⚠️ REQUIREMENT: If Priority events in next 14 days are listed above, include at least one generated option "
                "for each priority event unless that would conflict with safety rules."
            )

        delta_parts.append("\n🎉 " + celebrations_context + "\n")
        
        # CHAT HISTORY: rich mode keeps full recent history, fast mode keeps a compact tail.
        # This significantly reduces cache size/cost since messages change frequently
        if context_data["chat_history"]:
            recent_messages = context_data["chat_history"]

            if not include_rich_context:
                compact_messages: List[Dict[str, Any]] = []
                for msg in recent_messages[-8:]:
                    if not isinstance(msg, dict):
                        continue
                    compact_messages.append({
                        "question": str(msg.get("question", ""))[:120],
                        "response": str(msg.get("response", ""))[:180],
                        "timestamp": msg.get("timestamp"),
                    })
                delta_parts.append(
                    f"\n💬 RECENT CHAT SNAPSHOT (FAST MODE, last {len(compact_messages)} messages):\n"
                    f"{json.dumps(compact_messages, indent=2)}\n"
                )
                delta_string = "\n".join(delta_parts)
                logging.warning(
                    f"✅ DELTA context (FAST) for {account_id}/{aac_user_id} is {len(delta_string)} chars "
                    f"(~{len(delta_string)//4} tokens)"
                )
                logging.warning(f"📋 DELTA PREVIEW (first 500 chars): {delta_string[:500]}")
                return delta_string
            
            # Extract jokes from recent messages for explicit repetition avoidance
            recent_jokes = []
            for msg in recent_messages:
                response = msg.get("response", "").lower()
                # Check if it's likely a joke (contains common joke patterns)
                if any(pattern in response for pattern in ["why did", "what do you call", "how do you", "what's the difference"]):
                    # Extract the full joke text
                    joke_text = msg.get("response", "")[:200]  # First 200 chars
                    if joke_text:
                        recent_jokes.append(joke_text)
            
            # Add explicit joke avoidance warning if jokes were found
            if recent_jokes:
                joke_warning = "⚠️ CRITICAL - AVOID THESE RECENTLY USED JOKES:\n"
                for i, joke in enumerate(recent_jokes[:10], 1):  # Max 10 most recent
                    joke_warning += f"  {i}. {joke}\n"
                joke_warning += "\n🚫 DO NOT generate any of these jokes again. Create COMPLETELY NEW and DIFFERENT jokes.\n"
                delta_parts.append(f"--- Recently Used Jokes (DO NOT REPEAT) ---\n{joke_warning}\n")
            
            delta_parts.append(f"\n💬 RECENT CHAT HISTORY (Last {CHAT_HISTORY_ACTIVE_DAYS} days, {len(recent_messages)} messages):\n{json.dumps(recent_messages, indent=2)}\n")
            logging.warning(f"✅ Including ALL {len(recent_messages)} recent messages in DELTA (not cached)")
            logging.warning(f"📊 Chat history size: {len(json.dumps(recent_messages))} chars")
        
        # User-defined pages moved to BASE cache (too large for DELTA)
        
        delta_string = "\n".join(delta_parts)
        logging.warning(f"✅ DELTA context for {account_id}/{aac_user_id} is {len(delta_string)} chars (~{len(delta_string)//4} tokens)")
        logging.warning(f"📋 DELTA PREVIEW (first 500 chars): {delta_string[:500]}")
        return delta_string

    async def warm_up_user_cache_if_needed(self, account_id: str, aac_user_id: str) -> None:
        """
        Checks if a valid cache exists for the user. If not, it builds the
        combined context and creates a new Gemini CachedContent object.
        """
        print(f"DEBUG: warm_up_user_cache_if_needed ENTRY for {account_id}/{aac_user_id}", flush=True)
        logging.warning(f"🔥 WARMUP FUNCTION CALLED for account_id={account_id}, aac_user_id={aac_user_id}")
        user_key = self._get_user_key(account_id, aac_user_id)
        logging.warning(f"🔑 Generated user_key: {user_key}")
        if await self._is_cache_valid(user_key):
            logging.warning(f"Cache for user '{user_key}' is already warm and valid.")
            return

        logging.warning(f"Cache for user '{user_key}' is cold or invalid. Warming up...")
        print(f"DEBUG: About to build BASE context", flush=True)
        try:
            # Load consent before building so we can stamp the fingerprint on the cache record.
            _warmup_consent = await load_consent(account_id, aac_user_id)
            _warmup_fingerprint = (
                f"e={int(is_personalization_enabled(_warmup_consent))},"
                f"l={int(is_learning_enabled(_warmup_consent))}"
            )

            # Build BASE context only - stable data for caching
            base_context = await self._build_base_context(account_id, aac_user_id)

            # Gemini cached content rejects requests below 2048 total tokens in production.
            # Use a rough 4 chars/token estimate and skip cache creation when we are clearly under.
            estimated_tokens = len(base_context) // 4
            min_tokens_required = 2048
            
            logging.warning(f"✅ BASE context for user '{user_key}': {len(base_context)} chars, ~{int(estimated_tokens)} tokens")
            
            if estimated_tokens < min_tokens_required:
                logging.warning(f"BASE context for user '{user_key}' has {int(estimated_tokens)} tokens < {min_tokens_required} minimum. Skipping cache creation.")
                return
            
            logging.warning(f"🚀 Creating cache for user '{user_key}' with {int(estimated_tokens)} tokens (above {min_tokens_required} minimum)")

            # Create the cache using the Gemini API (BASE context only)
            cache_display_name = f"user_cache_{user_key}_{int(dt.now().timestamp())}"
            created_at = dt.now().timestamp()

            # system_instruction must be a separate field for Vertex AI caching
            cached_content = await _gemini_client.aio.caches.create(
                model=_primary_model_name,
                config=types.CreateCachedContentConfig(
                    display_name=cache_display_name,
                    system_instruction=_GEMINI_SYSTEM_INSTRUCTION,
                    contents=[{'role': 'user', 'parts': [{'text': base_context}]}],
                    ttl=f"{self.ttl_seconds}s",
                ),
            )

            # Save to Firestore (no message count since we don't cache chat anymore)
            await self._save_cache_to_firestore(
                user_key,
                cached_content.name,
                created_at,
                message_count=0,
                chat_history_cached=False,
                consent_fingerprint=_warmup_fingerprint,
            )
            logging.warning(f"✅ Successfully warmed up cache for user '{user_key}'. Cache: {cached_content.name} (chat history NOT cached - in DELTA)")

        except Exception as e:
            logging.error(f"Failed to warm up cache for user '{user_key}': {e}", exc_info=True)
            # Clean up any partial state from Firestore
            await self._delete_cache_from_firestore(user_key)

    async def get_cached_content_reference(self, account_id: str, aac_user_id: str) -> Optional[str]:
        """
        Returns the Gemini cache name (e.g., 'cachedContents/...') for the user
        if a valid cache exists (loaded from Firestore).
        """
        user_key = self._get_user_key(account_id, aac_user_id)
        
        if await self._is_cache_valid(user_key):
            cache_data = await self._load_cache_from_firestore(user_key)
            if cache_data:
                cache_name = cache_data.get('cache_name')
                logging.info(f"Found valid cache reference for user '{user_key}': {cache_name}")
                return cache_name
        
        logging.warning(f"No valid cache reference found for user '{user_key}'.")
        return None

    async def invalidate_cache(self, account_id: str, aac_user_id: str) -> None:
        """Invalidate and delete a user's cache. Provider first, Firestore second.

        A9b: the Firestore record is the only handle to the provider-side object.
        Deleting Firestore first means a provider failure orphans the cache with no
        way to find or retry it. Provider-first ordering fails safe: if the provider
        call fails, the Firestore record is preserved so a retry is possible.
        NOT_FOUND from the provider is treated as success (cache already expired).
        On genuine provider failure the record is marked pending_deletion so a
        future retry can locate it.
        """
        user_key = self._get_user_key(account_id, aac_user_id)
        cache_data = await self._load_cache_from_firestore(user_key)

        if not cache_data:
            logging.info(f"No cache to invalidate for user '{user_key}'.")
            return

        cache_name = cache_data.get('cache_name')
        provider_deleted = True

        if cache_name:
            try:
                await _gemini_client.aio.caches.delete(name=cache_name)
                logging.info(f"Successfully invalidated and deleted cache '{cache_name}' for user '{user_key}'.")
            except Exception as e:
                if "NOT_FOUND" in str(e) or "404" in str(e):
                    logging.info(f"Cache '{cache_name}' already absent at provider for user '{user_key}'.")
                else:
                    provider_deleted = False
                    logging.error(f"Error deleting Gemini cache '{cache_name}': {e}", exc_info=True)

        if provider_deleted:
            await self._delete_cache_from_firestore(user_key)
            logging.info(f"Deleted cache reference from Firestore: {user_key}")
        else:
            cache_data["pending_deletion"] = True
            await self._save_cache_to_firestore(user_key, cache_data)
            logging.warning(
                f"Cache '{cache_name}' for '{user_key}' marked pending_deletion — retry required."
            )

    async def get_cache_debug_info(self, account_id: str, aac_user_id: str) -> Dict:
        """Provides debugging information about a user's cache including drift stats."""
        user_key = self._get_user_key(account_id, aac_user_id)
        cache_data = await self._load_cache_from_firestore(user_key)

        if not cache_data:
            return {"status": "No active cache found."}
        
        cache_name = cache_data.get('cache_name')
        creation_time = cache_data.get('created_at', 0)
        messages_in_cache = cache_data.get('message_count', 0)

        age_seconds = dt.now().timestamp() - creation_time
        time_left_seconds = self.ttl_seconds - age_seconds
        is_valid = time_left_seconds > 0
        
        # Calculate current drift
        chat_history = await load_chat_history(account_id, aac_user_id)
        current_message_count = len(chat_history)
        drift = current_message_count - messages_in_cache

        return {
            "status": "Active" if is_valid else "Expired",
            "user_key": user_key,
            "cache_name": cache_name,
            "created_at": dt.fromtimestamp(creation_time).isoformat(),
            "expires_at": dt.fromtimestamp(creation_time + self.ttl_seconds).isoformat(),
            "age_minutes": round(age_seconds / 60, 2),
            "time_left_minutes": round(time_left_seconds / 60, 2),
            "is_valid": is_valid,
            "messages_in_cache": messages_in_cache,
            "current_message_count": current_message_count,
            "drift": drift,
            "drift_percentage": round((drift / messages_in_cache * 100) if messages_in_cache > 0 else 0, 1)
        }
    
    async def check_cache_drift(self, account_id: str, aac_user_id: str, max_drift: int = 20) -> Dict:
        """
        Check if cache drift exceeds threshold and should be rebuilt.
        Returns dict with should_rebuild flag and drift statistics.
        
        Args:
            account_id: Account ID
            aac_user_id: AAC User ID  
            max_drift: Maximum acceptable drift (new messages) before rebuilding cache
            
        Returns:
            Dict with should_rebuild, reason, drift, and message counts
        """
        user_key = self._get_user_key(account_id, aac_user_id)
        cache_data = await self._load_cache_from_firestore(user_key)

        if not cache_data:
            return {"should_rebuild": True, "reason": "no_cache", "drift": 0}

        # Consent fingerprint check: rebuild if personalization/learning flags have changed
        # since the cache was built, or if the cache predates fingerprint tracking.
        stored_fingerprint = cache_data.get("consent_fingerprint", "")
        current_consent = await load_consent(account_id, aac_user_id)
        current_fingerprint = (
            f"e={int(is_personalization_enabled(current_consent))},"
            f"l={int(is_learning_enabled(current_consent))}"
        )
        if stored_fingerprint != current_fingerprint:
            logging.info(
                f"Consent fingerprint mismatch for '{user_key}': "
                f"cached={stored_fingerprint!r} current={current_fingerprint!r} — rebuilding."
            )
            return {"should_rebuild": True, "reason": "consent_changed", "drift": 0}

        messages_in_cache = cache_data.get('message_count', 0)
        chat_history_cached = cache_data.get('chat_history_cached')

        # Chat history is no longer part of the cached BASE context. For those caches,
        # rebuilding on chat drift only destroys the cache benefit without improving relevance.
        if chat_history_cached is False or messages_in_cache == 0:
            return {
                "should_rebuild": False,
                "reason": "chat_history_not_cached",
                "drift": 0,
                "max_drift": max_drift,
                "messages_in_cache": messages_in_cache,
                "current_message_count": None,
            }
        
        # Get current message count
        chat_history = await load_chat_history(account_id, aac_user_id)
        current_message_count = len(chat_history)
        drift = current_message_count - messages_in_cache
        
        if drift >= max_drift:
            return {
                "should_rebuild": True,
                "reason": "drift_threshold_exceeded",
                "drift": drift,
                "max_drift": max_drift,
                "messages_in_cache": messages_in_cache,
                "current_message_count": current_message_count
            }
        
        return {
            "should_rebuild": False,
            "drift": drift,
            "max_drift": max_drift,
            "messages_in_cache": messages_in_cache,
            "current_message_count": current_message_count
        }
    
    async def cleanup_expired_caches_globally(self):
        """Background task to clean up expired caches across all users."""
        try:
            logging.info("🧹 Running global cache cleanup...")
            
            docs = await asyncio.to_thread(
                lambda: list(self.db.collection(self.CACHE_COLLECTION).stream())
            )
            
            now = dt.now().timestamp()
            cleaned = 0
            
            for doc in docs:
                data = doc.to_dict()
                created_at = data.get('created_at', 0)
                user_key = data.get('user_key')
                cache_name = data.get('cache_name')
                
                if (now - created_at) > self.ttl_seconds:
                    # Expired - delete it
                    await self._delete_expired_cache(user_key, cache_name)
                    cleaned += 1
            
            logging.info(f"✅ Global cache cleanup complete: cleaned {cleaned} expired caches")
            
        except Exception as e:
            logging.error(f"Error during global cache cleanup: {e}", exc_info=True)

# Initialize global cache manager
cache_manager = GeminiCacheManager()

