# ================================

@app.post("/api/admin/repair-bravo-images")
async def repair_bravo_images_endpoint(
    current_ids: Annotated[Dict[str, str], Depends(get_current_account_and_user_ids)]
):
    """Admin endpoint to repair BravoImages with truncated subconcepts"""
    account_id = current_ids["account_id"]
    user_email = current_ids.get("email", "")
    
    # Admin access only
    if user_email != "admin@talkwithbravo.com":
        raise HTTPException(status_code=403, detail="Admin access required")
    
    try:
        # Import required libraries
        from google.cloud import firestore
        from google.cloud import storage as gcs
        import time
        import re
        
        # Initialize clients (using server's existing configuration)
        db = firestore_db
        if not db:
            raise HTTPException(status_code=503, detail="Firestore not initialized")
        
        storage_client = gcs.Client()
        bucket = storage_client.bucket('bravo-image-db')
        
        logging.info("🔧 Starting BravoImages repair process...")
        
        # Step 1: Find all BravoImages documents
        bravo_images_ref = db.collection('BravoImages')
        docs = bravo_images_ref.stream()
        
        problematic_images = []
        total_checked = 0
        
        # Step 2: Check each image for truncated subconcepts
        for doc in docs:
            total_checked += 1
            data = doc.to_dict()
            
            if not data:
                continue
                
            subconcept = data.get('subconcept', '')
            image_url = data.get('image_url', '')
            
            # Skip if no image_url to reconstruct from
            if not image_url:
                continue
            
            # Extract filename from URL for analysis
            filename = image_url.split('/')[-1] if '/' in image_url else ''
            
            if not filename:
                continue
            
            # Check if this looks like a truncated subconcept
            # Pattern: subconcept is single word but filename suggests multi-word
            if subconcept and '_' not in subconcept and len(subconcept.split()) == 1:
                # Check if filename has multiple words (indicated by underscores before timestamp)
                # Expected pattern: word1_word2_word3_YYYYMMDD_HHMMSS.ext
                name_without_ext = filename.rsplit('.', 1)[0]
                parts = name_without_ext.split('_')
                
                # Look for timestamp pattern (YYYYMMDD_HHMMSS)
                timestamp_found = False
                timestamp_index = -1
                
                for i, part in enumerate(parts):
                    if re.match(r'^\d{8}$', part) and i + 1 < len(parts) and re.match(r'^\d{6}$', parts[i + 1]):
                        timestamp_found = True
                        timestamp_index = i
                        break
                
                if timestamp_found and timestamp_index > 1:
                    # Reconstruct the full subconcept (everything before timestamp)
                    reconstructed_subconcept = '_'.join(parts[:timestamp_index])
                    
                    if reconstructed_subconcept != subconcept:
                        problematic_images.append({
                            'doc_id': doc.id,
                            'current_subconcept': subconcept,
                            'reconstructed_subconcept': reconstructed_subconcept,
                            'filename': filename,
                            'image_url': image_url,
                            'doc_data': data
                        })
        
        logging.info(f"🔍 Checked {total_checked} images, found {len(problematic_images)} with truncated subconcepts")
        
        if not problematic_images:
            return JSONResponse(content={
                "success": True,
                "message": f"No truncated subconcepts found. Checked {total_checked} images.",
                "repaired_count": 0,
                "total_checked": total_checked
            })
        
        # Step 3: Repair each problematic image
        repaired_count = 0
        failed_repairs = []
        
        for img_data in problematic_images[:50]:  # Process in batches of 50
            try:
                doc_id = img_data['doc_id']
                new_subconcept = img_data['reconstructed_subconcept']
                old_subconcept = img_data['current_subconcept']
                
                logging.info(f"🔧 Repairing {doc_id}: '{old_subconcept}' → '{new_subconcept}'")
                
                # Generate new tags for the corrected subconcept
                try:
                    tag_prompt = f"""Generate descriptive tags for an AAC (Augmentative and Alternative Communication) image with the concept: "{new_subconcept}".

The tags should help users find this image when searching. Consider:
- The literal meaning of "{new_subconcept}"
- Related emotional states, actions, or contexts
- Alternative words someone might search for
- Both simple and complex vocabulary levels

Return 8-12 relevant tags as a comma-separated list. Make tags specific and useful for AAC communication."""

                    response = await _gemini_client.aio.models.generate_content(
                        model=_primary_model_name,
                        contents=tag_prompt,
                        config={"temperature": 0.7},
                    )
                    
                    new_tags_text = response.text.strip()
                    new_tags = [tag.strip() for tag in new_tags_text.split(',')]
                    new_tags = [tag for tag in new_tags if tag]  # Remove empty tags
                    
                    if not new_tags:
                        new_tags = [new_subconcept.replace('_', ' ')]
                    
                except Exception as tag_error:
                    logging.warning(f"Failed to generate new tags for {doc_id}: {tag_error}")
                    new_tags = [new_subconcept.replace('_', ' ')]
                
                # Update the document
                update_data = {
                    'subconcept': new_subconcept,
                    'tags': new_tags,
                    'repaired_at': firestore.SERVER_TIMESTAMP,
                    'repair_info': {
                        'old_subconcept': old_subconcept,
                        'repair_method': 'filename_reconstruction',
                        'repaired_by': 'admin_repair_endpoint'
                    }
                }
                
                # Update in Firestore
                bravo_images_ref.document(doc_id).update(update_data)
                repaired_count += 1
                
                # Small delay to avoid rate limits
                if repaired_count % 10 == 0:
                    await asyncio.sleep(1)
                
            except Exception as repair_error:
                logging.error(f"Failed to repair {img_data['doc_id']}: {repair_error}")
                failed_repairs.append({
                    'doc_id': img_data['doc_id'],
                    'error': str(repair_error)
                })
        
        success_message = f"✅ Repair completed! Repaired {repaired_count} images out of {len(problematic_images)} identified."
        if failed_repairs:
            success_message += f" {len(failed_repairs)} repairs failed."
        
        logging.info(success_message)
        
        return JSONResponse(content={
            "success": True,
            "message": success_message,
            "repaired_count": repaired_count,
            "failed_count": len(failed_repairs),
            "total_problematic": len(problematic_images),
            "total_checked": total_checked,
            "failed_repairs": failed_repairs[:5]  # Include first 5 failures for debugging
        })
        
    except Exception as e:
        error_msg = f"BravoImages repair failed: {str(e)}"
        logging.error(error_msg, exc_info=True)
        raise HTTPException(status_code=500, detail=error_msg)

@app.post("/api/symbols/import-aac-generated")
async def import_aac_generated_symbols(
    request_data: dict,
    admin_user: Annotated[Dict[str, str], Depends(verify_admin_user)]
):
    """Import Gemini-generated AAC symbols directly into the database"""
    logging.info(f"POST /api/symbols/import-aac-generated request for admin user {admin_user.get('email')}")
    
    try:
        import uuid
        from datetime import datetime
        
        symbols_data = request_data.get("symbols", [])
        batch_size = request_data.get("batch_size", 10)
        
        if not symbols_data:
            return JSONResponse(
                status_code=400,
                content={"error": "No symbols provided for import"}
            )
        
        processed_symbols = []
        errors = []
        
        for symbol_data in symbols_data[:batch_size]:
            try:
                # Create AAC symbol document
                symbol_doc = {
                    'symbol_id': str(uuid.uuid4()),
                    'name': symbol_data['name'],
                    'name_lower': symbol_data['name'].lower(),
                    'description': symbol_data['description'],
                    'tags': symbol_data.get('tags', []),
                    'categories': symbol_data.get('categories', ['descriptors']),
                    'primary_category': symbol_data.get('categories', ['descriptors'])[0],
                    'age_groups': symbol_data.get('age_groups', ['all']),
                    'difficulty_level': symbol_data.get('difficulty_level', 'simple'),
                    'search_weight': symbol_data.get('search_weight', 2),
                    'filename': f"{symbol_data['name']}.png",
                    'source': 'gemini_generated_aac',
                    'image_url': symbol_data.get('image_url', ''),
                    'thumbnail_url': symbol_data.get('image_url', ''),  # Use same as main image for now
                    'alt_text': f"AAC symbol showing {symbol_data['name']}",
                    'usage_contexts': ["General communication", "Descriptive words"],
                    'usage_frequency': 0,
                    'last_used': None,
                    'created_at': datetime.utcnow(),
                    'updated_at': datetime.utcnow(),
                    'processing_status': 'processed_with_ai',
                    
                    # Additional AAC-specific metadata
                    'source_id': f"gemini_aac_{int(datetime.utcnow().timestamp())}",
                    'filename_tags': [symbol_data['name']],
                    'filename_analysis': {
                        'word_count': 1,
                        'difficulty': symbol_data.get('difficulty_level', 'simple'),
                        'categories': symbol_data.get('categories', ['descriptors']),
                        'tags': symbol_data.get('tags', []),
                        'description': symbol_data['description'],
                        'generation_source': 'gemini_aac_generator'
                    }
                }
                
                # Save to Firestore
                symbols_ref = firestore_db.collection("aac_images")
                doc_ref = symbols_ref.document(symbol_doc['symbol_id'])
                doc_ref.set(symbol_doc)
                
                processed_symbols.append({
                    'symbol_id': symbol_doc['symbol_id'],
                    'name': symbol_data['name'],
                    'tags': symbol_doc['tags'],
                    'categories': symbol_doc['categories']
                })
                
                logging.info(f"Imported AAC symbol: {symbol_data['name']}")
                
            except Exception as e:
                errors.append(f"Error importing {symbol_data.get('name', 'unknown')}: {str(e)}")
                logging.error(f"Error importing AAC symbol {symbol_data.get('name', 'unknown')}: {e}")
        
        return JSONResponse(content={
            "success": True,
            "imported_count": len(processed_symbols),
            "total_requested": len(symbols_data),
            "imported_symbols": processed_symbols,
            "errors": errors,
            "error_count": len(errors),
            "message": f"Successfully imported {len(processed_symbols)} AAC symbols to database"
        })
        
    except Exception as e:
        logging.error(f"Error in import_aac_generated_symbols: {e}")
        return JSONResponse(
            status_code=500,
            content={"error": "AAC symbol import failed", "details": str(e)}
        )

@app.get("/api/symbols/button-search")
async def button_symbol_search(
    current_ids: Annotated[Dict[str, str], Depends(get_current_account_and_user_ids)],
    q: str = "",
    keywords: str = "",
    locale: str = "en-US",
    limit: int = 5,
    mascot: str = ""
):
    """
    Fast AAC button symbol search with keyword matching and AI fallback.
    Uses optimized Firestore queries for speed, with semantic matching as backup.
    Supports both text queries and keyword arrays for LLM-generated content.
    """
    try:
        if not q:
            return JSONResponse(content={
                "symbols": [],
                "total_found": 0,
                "query": q,
                "search_type": "empty_query"
            })
        
        query_lower = q.lower().strip()
        locale_norm = str(locale or "en-US").strip().lower()
        locale_base = locale_norm.split('-')[0] if '-' in locale_norm else locale_norm

        # Normalize inflected forms (e.g., "quiero" -> "querer") for locale-aware lookup.
        normalized_query = query_lower
        if locale_base and locale_base != "en":
            try:
                from aac_inflection_utils import normalize_search_term
                inflection_normalized = str(normalize_search_term(query_lower, locale_base) or "").strip().lower()
                if inflection_normalized:
                    normalized_query = inflection_normalized
            except Exception as inflection_error:
                logging.debug(f"Inflection normalization skipped for '{query_lower}' ({locale_base}): {inflection_error}")

        def _allowed_locale_keys():
            keys = {"en", "en-us", locale_norm, locale_base}
            return {k for k in keys if k}

        allowed_locale_keys = _allowed_locale_keys()

        def _extract_localized_terms_for_locale(localized_tags_raw, localized_labels_raw):
            localized_terms = []

            if isinstance(localized_tags_raw, dict):
                for locale_key, locale_tags in localized_tags_raw.items():
                    locale_key_norm = str(locale_key or "").strip().lower()
                    if locale_key_norm not in allowed_locale_keys:
                        continue
                    if isinstance(locale_tags, list):
                        localized_terms.extend([
                            str(tag).strip().lower()
                            for tag in locale_tags
                            if str(tag).strip()
                        ])

            if isinstance(localized_labels_raw, dict):
                for locale_key, locale_label in localized_labels_raw.items():
                    locale_key_norm = str(locale_key or "").strip().lower()
                    if locale_key_norm not in allowed_locale_keys:
                        continue
                    if isinstance(locale_label, str) and locale_label.strip():
                        localized_terms.append(locale_label.strip().lower())

            return localized_terms
        
        # Process keywords if provided (for LLM-generated content)
        keyword_list = []
        if keywords:
            try:
                # Keywords come as JSON array string from frontend
                import json
                parsed_keywords = json.loads(keywords)
                if isinstance(parsed_keywords, list):
                    keyword_list = [kw.strip().lower() for kw in parsed_keywords if isinstance(kw, str) and kw.strip()]
                else:
                    # Fallback for comma-separated format
                    keyword_list = [kw.strip().lower() for kw in keywords.split(',') if kw.strip()]
            except Exception as e:
                logging.debug(f"Failed to parse keywords '{keywords}': {e}")
                # Fallback for comma-separated format
                try:
                    keyword_list = [kw.strip().lower() for kw in keywords.split(',') if kw.strip()]
                except:
                    pass
        
        logging.info(f"Symbol search: query='{query_lower}', locale='{locale_norm}', keywords={keyword_list}")
        
        # Semantic mapping for common AAC terms
        semantic_mappings = {
            # Emotions & expressions
            "smile": ["happy", "joy", "cheerful"], "smiling": ["happy", "joy", "cheerful"],
            "laugh": ["happy", "joy", "funny"], "laughing": ["happy", "joy", "funny"],
            "frown": ["sad", "unhappy"], "cry": ["sad", "tears"], "crying": ["sad", "tears"],
            "angry": ["mad", "upset"], "mad": ["angry", "upset"], "upset": ["angry", "sad"],
            
            # Actions & activities
            "eat": ["food", "eating"], "drink": ["drinking", "water"], "sleep": ["bed", "tired"],
            "walk": ["walking", "go"], "run": ["running", "fast"], "play": ["playing", "fun"],
            "work": ["working", "job"], "read": ["reading", "book"], "write": ["writing", "pencil"],
            
            # Social interactions
            "hello": ["greeting", "hi"], "hi": ["greeting", "hello"], 
            "greetings": ["greeting", "hello", "hi"], "greeting": ["greetings", "hello"],
            "goodbye": ["bye", "farewell"], "bye": ["goodbye", "farewell"], 
            "thanks": ["thank", "grateful"], "sorry": ["apologize", "regret"],
            
            # Basic needs & descriptors
            "hungry": ["food", "eat"], "thirsty": ["drink", "water"], "tired": ["sleep", "rest"],
            "big": ["large", "huge"], "small": ["little", "tiny"], "fast": ["quick", "speed"],
        }
        
        matched_symbols = []
        
        # Search both collections - prioritize aac_images (BravoImages)
        symbols_ref = firestore_db.collection("aac_images")
        images_ref = firestore_db.collection("aac_images")
        
        # Phase -1: Search BravoImages (aac_images) collection first - these are prioritized
        search_terms_for_images = []
        if query_lower:
            search_terms_for_images.append(query_lower)
        if normalized_query and normalized_query != query_lower:
            search_terms_for_images.append(normalized_query)
        search_terms_for_images.extend(keyword_list[:3])  # Add up to 3 keywords
        search_terms_for_images = list(dict.fromkeys(search_terms_for_images))  # Remove duplicates
        
        for i, term in enumerate(search_terms_for_images[:3]):  # Check up to 3 terms for images
            try:
                # Search bravo_images in aac_images collection using precomputed search_terms first,
                # then legacy tags as fallback.
                term_variations = [
                    term,                    # Original case
                    term.lower(),            # All lowercase  
                    term.capitalize(),       # First letter capitalized
                    term.title()             # Title case (capitalizes each word)
                ]
                
                # Remove duplicates while preserving order
                seen = set()
                unique_variations = []
                for variation in term_variations:
                    if variation not in seen:
                        seen.add(variation)
                        unique_variations.append(variation)
                
                # Try each variation until we find results (prioritize exact match first)
                image_docs = []
                for variation in unique_variations:
                    try:
                        variation_lower = variation.lower().strip()
                        if not variation_lower:
                            continue

                        # Preferred path: language-friendly array field
                        variation_query = images_ref.where("search_terms", "array_contains", variation_lower).limit(max(30, limit * 8))
                        variation_docs = list(variation_query.stream())
                        for d in variation_docs:
                            data = d.to_dict() or {}
                            if data.get("source") == "bravo_images":
                                image_docs.append(d)

                        # Locale-aware fallback path for migrated data where localized tags/labels exist
                        # but search_terms may be incomplete/stale.
                        if locale_base and locale_base != "en":
                            localized_tags_field = f"localized_tags.{locale_base}"
                            localized_labels_field = f"localized_labels.{locale_base}"

                            localized_tag_query = images_ref.where("source", "==", "bravo_images").where(
                                localized_tags_field, "array_contains", variation_lower
                            ).limit(max(20, limit * 5))
                            image_docs.extend(list(localized_tag_query.stream()))

                            for label_candidate in [variation.strip(), variation_lower]:
                                if not label_candidate:
                                    continue
                                localized_label_query = images_ref.where("source", "==", "bravo_images").where(
                                    localized_labels_field, "==", label_candidate
                                ).limit(max(10, limit * 3))
                                image_docs.extend(list(localized_label_query.stream()))

                        # Legacy fallback path
                        if not variation_docs:
                            legacy_query = images_ref.where("source", "==", "bravo_images").where("tags", "array_contains", variation).limit(max(20, limit * 5))
                            legacy_docs = list(legacy_query.stream())
                            image_docs.extend(legacy_docs)
                        
                        # Don't stop at first match - collect from all variations for better scoring
                    except Exception as e:
                        logging.debug(f"Query failed for variation '{variation}': {e}")
                        continue
                # Process all collected docs (dedupe by document id first)
                deduped_docs = {}
                for d in image_docs:
                    deduped_docs[d.id] = d

                weight = 1.0 if i == 0 else 0.8
                for doc in deduped_docs.values():
                    image = doc.to_dict()
                    image_id = doc.id
                    
                    # Avoid duplicates
                    if not any(s['id'] == image_id for s in matched_symbols):
                        image['id'] = image_id
                        
                        # Calculate tag position bonus - first tag gets highest score
                        tags = image.get('tags', [])
                        tags_lower = [str(tag).lower() for tag in tags]
                        image_subconcept = str(image.get('subconcept', '')).lower().strip()
                        image_concept = str(image.get('concept', '')).lower().strip()
                        tag_position_bonus = 0
                        for pos, tag in enumerate(tags):
                            if tag.lower() == term.lower():
                                if pos == 0:
                                    tag_position_bonus = 20  # First tag gets big bonus for BravoImages
                                elif pos == 1:
                                    tag_position_bonus = 10  # Second tag gets medium bonus
                                elif pos <= 3:
                                    tag_position_bonus = 5   # Early tags get small bonus
                                break
                        
                        # PRIORITY RULE: exact subconcept match must outrank tag matches.
                        if image_subconcept and image_subconcept == term.lower():
                            image['match_score'] = (95 * weight) + tag_position_bonus
                        elif image_concept and image_concept == term.lower():
                            image['match_score'] = (85 * weight) + tag_position_bonus
                        elif term.lower() in tags_lower:
                            # Keep tag-only matches below subconcept/concept exact matches.
                            base_score = 50 * weight
                            image['match_score'] = base_score + tag_position_bonus
                        else:
                            image['match_score'] = 40 * weight
                        image['matched_term'] = term
                        image['search_phase'] = "bravo_image_match"
                        
                        # Convert image format to symbol format for compatibility
                        symbol_data = {
                            'id': image_id,
                            'url': _display_image_url(image.get('image_url'), image.get('storage_path')),
                            'name': image.get('subconcept', image.get('concept', 'BravoImage')),
                            'description': f"Bravo Image: {image.get('subconcept', '')}",
                            'tags': tags,
                            'match_score': image['match_score'],
                            'matched_term': term,
                            'search_phase': "bravo_image_match",
                            'source': 'bravo_images',
                            'mascot': image.get('mascot')
                        }
                        matched_symbols.append(symbol_data)
            except Exception as e:
                logging.debug(f"BravoImages search failed for term '{term}': {e}")
        
        logging.info(f"Found {len(matched_symbols)} BravoImages matches")

        # Phase -0.5: Search user's custom images (including profile images)
        # NOTE: Must happen BEFORE the fast-return path so custom subconcept matches
        # can outrank BravoImage tag matches even when limit=1 (Tap interface).
        account_id = current_ids["account_id"]
        aac_user_id = current_ids["aac_user_id"]
        
        try:
            # Search user's custom images collection
            custom_images_ref = firestore_db.collection("accounts").document(account_id)\
                                          .collection("profiles").document(aac_user_id)\
                                          .collection("custom_images")

            # Build a targeted candidate set first so exact subconcept matches are not
            # missed when limit=1 (Tap calls often request only one result).
            custom_doc_map: Dict[str, Any] = {}

            def _collect_custom_docs(doc_iterable):
                for custom_doc in doc_iterable:
                    custom_doc_map[custom_doc.id] = custom_doc

            targeted_limit = max(50, limit * 20)

            # Single-field queries avoid composite-index requirements and are reliable.
            try:
                _collect_custom_docs(custom_images_ref.where("subconcept", "==", query_lower).limit(targeted_limit).stream())
            except Exception as e:
                logging.debug(f"Custom subconcept query failed: {e}")

            try:
                _collect_custom_docs(custom_images_ref.where("concept", "==", query_lower).limit(targeted_limit).stream())
            except Exception as e:
                logging.debug(f"Custom concept query failed: {e}")

            try:
                _collect_custom_docs(custom_images_ref.where("tags", "array_contains", query_lower).limit(targeted_limit).stream())
            except Exception as e:
                logging.debug(f"Custom tags query failed: {e}")

            try:
                _collect_custom_docs(custom_images_ref.where("aliases", "array_contains", query_lower).limit(targeted_limit).stream())
            except Exception as e:
                logging.debug(f"Custom aliases query failed: {e}")

            if locale_base and locale_base != "en":
                localized_tags_field = f"localized_tags.{locale_base}"
                localized_labels_field = f"localized_labels.{locale_base}"

                try:
                    _collect_custom_docs(custom_images_ref.where(localized_tags_field, "array_contains", query_lower).limit(targeted_limit).stream())
                except Exception as e:
                    logging.debug(f"Custom localized tags query failed: {e}")

                for label_candidate in [query_lower, q.strip()]:
                    if not label_candidate:
                        continue
                    try:
                        _collect_custom_docs(custom_images_ref.where(localized_labels_field, "==", label_candidate).limit(targeted_limit).stream())
                    except Exception as e:
                        logging.debug(f"Custom localized label query failed for '{label_candidate}': {e}")

            # Fallback broad scan to preserve previous behavior for legacy data where
            # searchable fields may be incomplete.
            fallback_scan_limit = max(200, limit * 60)
            if len(custom_doc_map) < max(20, limit * 10):
                try:
                    fallback_query = custom_images_ref.where("active", "==", True).limit(fallback_scan_limit)
                    _collect_custom_docs(fallback_query.stream())
                except Exception as e:
                    logging.debug(f"Custom fallback active query failed: {e}")

            custom_docs = list(custom_doc_map.values())
            logging.info(f"Collected {len(custom_docs)} custom image candidates for search matching")
            
            for doc in custom_docs:
                custom_image = doc.to_dict()
                custom_image_id = doc.id

                # Enforce active-only behavior after collecting candidates.
                if not custom_image.get('active', False):
                    continue
                
                # Get all searchable fields
                tags = custom_image.get('tags', [])
                tags_lower = [tag.lower() for tag in tags]
                concept = custom_image.get('concept', '').lower()
                subconcept = custom_image.get('subconcept', '').lower()
                aliases = custom_image.get('aliases', [])
                aliases_lower = [str(alias).strip().lower() for alias in aliases if isinstance(alias, (str, int, float)) and str(alias).strip()]

                localized_tags_raw = custom_image.get('localized_tags')
                localized_labels_raw = custom_image.get('localized_labels')
                localized_terms_lower = _extract_localized_terms_for_locale(localized_tags_raw, localized_labels_raw)

                all_search_terms_lower = [term for term in [concept, subconcept, *tags_lower, *aliases_lower, *localized_terms_lower] if term]
                
                # Debug logging for each image
                logging.info(f"Checking custom image {custom_image_id}: concept='{concept}', subconcept='{subconcept}', tags={tags}")
                logging.info(f"Query term: '{query_lower}', looking for matches...")
                
                matched_term = None
                match_score = 0
                tag_position_bonus = 0
                
                # Check primary query against all fields
                if query_lower == concept:
                    matched_term = query_lower
                    match_score = 70
                    logging.info(f"✅ EXACT CONCEPT MATCH: '{query_lower}' == '{concept}' (score: {match_score})")
                elif query_lower == subconcept:
                    matched_term = query_lower  
                    match_score = 95  # Highest priority for exact subcategory/subconcept match
                    logging.info(f"✅ EXACT SUBCONCEPT MATCH: '{query_lower}' == '{subconcept}' (score: {match_score})")
                elif query_lower in tags_lower:
                    matched_term = query_lower
                    # Find position of matching tag
                    for pos, tag in enumerate(tags):
                        if tag.lower() == query_lower:
                            if pos == 0:
                                tag_position_bonus = 25  # Custom images get highest bonus
                            elif pos == 1:
                                tag_position_bonus = 15
                            elif pos <= 3:
                                tag_position_bonus = 8
                            break
                    match_score = 60 + tag_position_bonus
                elif query_lower in aliases_lower:
                    matched_term = query_lower
                    match_score = 58
                elif query_lower in localized_terms_lower:
                    matched_term = query_lower
                    match_score = 56
                elif query_lower in concept:
                    matched_term = query_lower
                    match_score = 45  # Partial concept match
                elif query_lower in subconcept:
                    matched_term = query_lower
                    match_score = 40  # Partial subconcept match
                elif any(query_lower in term for term in all_search_terms_lower):
                    matched_term = query_lower
                    match_score = 36
                
                # Check keyword list if no primary match
                if not matched_term:
                    for keyword in keyword_list:
                        if keyword == concept:
                            matched_term = keyword
                            match_score = 65
                            break
                        elif keyword == subconcept:
                            matched_term = keyword
                            match_score = 90  # Keep keyword-driven subconcept exact above tag hits
                            break
                        elif keyword in tags_lower:
                            matched_term = keyword
                            for pos, tag in enumerate(tags):
                                if tag.lower() == keyword:
                                    if pos == 0:
                                        tag_position_bonus = 20
                                    elif pos == 1:
                                        tag_position_bonus = 12
                                    elif pos <= 3:
                                        tag_position_bonus = 6
                                    break
                            match_score = 55 + tag_position_bonus
                            break
                        elif keyword in aliases_lower:
                            matched_term = keyword
                            match_score = 52
                            break
                        elif keyword in localized_terms_lower:
                            matched_term = keyword
                            match_score = 50
                            break
                        elif keyword in concept:
                            matched_term = keyword
                            match_score = 35
                            break
                        elif keyword in subconcept:
                            matched_term = keyword
                            match_score = 30
                            break
                        elif any(keyword in term for term in all_search_terms_lower):
                            matched_term = keyword
                            match_score = 28
                            break
                
                if matched_term:
                    logging.info(f"✅ MATCHED custom image {custom_image_id} with term '{matched_term}' (score: {match_score})")
                    # Avoid duplicates
                    if not any(s['id'] == custom_image_id for s in matched_symbols):
                        # Convert to symbol format for compatibility
                        symbol_data = {
                            'id': custom_image_id,
                            'url': _display_image_url(custom_image.get('image_url'), custom_image.get('storage_path')),
                            'name': custom_image.get('subconcept', custom_image.get('concept', 'Custom Image')),
                            'description': f"Custom Image: {custom_image.get('subconcept', '')}",
                            'tags': tags,
                            'match_score': match_score,
                            'matched_term': matched_term,
                            'search_phase': "custom_image_match",
                            'source': 'custom_images',
                            'is_profile_image': custom_image.get('is_profile_image', False)
                        }
                        matched_symbols.append(symbol_data)
                else:
                    logging.info(f"❌ NO MATCH for custom image {custom_image_id}: concept='{concept}', subconcept='{subconcept}', tags={tags} - query was '{query_lower}'")
                        
            logging.info(f"Found {len([s for s in matched_symbols if s.get('source') == 'custom_images'])} custom images matches")
            
        except Exception as e:
            logging.debug(f"Custom images search failed: {e}")

        def _apply_mascot_scores(symbols: list, selected_mascot: str) -> list:
            """Boost mascot-matching images, penalize wrong-mascot images, leave generic neutral.
            Scores must dominate text match variance (text scores go up to ~900) so mascot
            preference is always respected: correct > generic > wrong mascot."""
            if not selected_mascot:
                return symbols
            for s in symbols:
                img_mascot = s.get('mascot')
                if img_mascot == selected_mascot:
                    s['match_score'] = s.get('match_score', 0) + 1000
                elif img_mascot and img_mascot != selected_mascot:
                    s['match_score'] = s.get('match_score', 0) - 1000
            return symbols

        # Fast return path for Tap interface (limit=1): avoid expensive fallback phases.
        # Placed here (after custom images) so custom subconcept/concept matches are included.
        if limit <= 1 and matched_symbols:
            _apply_mascot_scores(matched_symbols, mascot)
            matched_symbols.sort(key=lambda x: x.get('match_score', 0), reverse=True)
            return JSONResponse(content={
                "symbols": matched_symbols[:1],
                "total_found": len(matched_symbols),
                "query": q,
                "search_type": "bravo_image_fast"
            })

        # Phase 0: Enhanced keyword array matching for LLM-generated content (when keywords are provided)
        if keyword_list:
            try:
                # Combine keywords with individual words from the query for better coverage
                query_words = [word.strip().lower() for word in query_lower.split() if len(word.strip()) > 2]
                search_terms = list(set(keyword_list + query_words))  # Remove duplicates
                
                logging.info(f"Search terms: keywords={keyword_list}, query_words={query_words}, combined={search_terms}")
                
                # Use array-contains-any query for efficient keyword matching
                keyword_query = symbols_ref.where("tags", "array_contains_any", search_terms[:10]).limit(limit * 2)
                keyword_results = keyword_query.stream()
                
                for doc in keyword_results:
                    symbol = doc.to_dict()
                    symbol['id'] = doc.id
                    
                    # Score based on how many terms match (keywords get higher weight)
                    symbol_tags = symbol.get('tags', [])
                    symbol_tags_lower = [tag.lower() for tag in symbol_tags]
                    matched_keywords = [kw for kw in keyword_list if kw in symbol_tags_lower]
                    matched_words = [word for word in query_words if word in symbol_tags_lower]
                    
                    # Weight keywords more heavily than query words
                    keyword_score = len(matched_keywords) * 2
                    word_score = len(matched_words) * 1
                    total_possible = len(keyword_list) * 2 + len(query_words) * 1
                    
                    # Add tag position bonus for first-tag matches
                    tag_position_bonus = 0
                    all_search_terms = search_terms[:3]  # Check top search terms
                    for term in all_search_terms:
                        for pos, tag in enumerate(symbol_tags):
                            if tag.lower() == term.lower():
                                if pos == 0:
                                    tag_position_bonus += 8  # First tag gets bonus
                                elif pos == 1:
                                    tag_position_bonus += 4  # Second tag gets smaller bonus
                                break
                    
                    if total_possible > 0:
                        match_ratio = (keyword_score + word_score) / total_possible
                        base_score = 30 + (match_ratio * 20)  # 30-50 points based on match ratio
                        symbol['match_score'] = base_score + tag_position_bonus
                    else:
                        symbol['match_score'] = 35 + tag_position_bonus
                    
                    matched_terms = matched_keywords + matched_words
                    symbol['matched_term'] = ', '.join(matched_terms) if matched_terms else 'keyword_match'
                    symbol['search_phase'] = "keyword_array_match"
                    matched_symbols.append(symbol)
                    
                logging.info(f"Found {len(matched_symbols)} symbols via enhanced keyword array matching")
            except Exception as e:
                logging.debug(f"Keyword array query failed: {e}")
        
        # Phase 1: Fast exact name matches using Firestore queries
        try:
            exact_query = symbols_ref.where("name_lower", "==", query_lower).limit(limit)
            exact_results = exact_query.stream()
            
            for doc in exact_results:
                symbol = doc.to_dict()
                symbol['id'] = doc.id
                symbol['match_score'] = 25  # Highest score for exact matches
                symbol['matched_term'] = query_lower
                symbol['search_phase'] = "exact_match"
                matched_symbols.append(symbol)
        except Exception as e:
            logging.debug(f"Exact match query failed: {e}")
        
        # Phase 2: Fast tag-based searches for all relevant terms (no early return)
        search_terms = []
        if query_lower:
            search_terms.append(query_lower)
            if query_lower in semantic_mappings:
                search_terms.extend(semantic_mappings[query_lower])
        
        # Add keywords to search terms if provided
        search_terms.extend(keyword_list[:3])  # Add up to 3 keywords
        search_terms = list(dict.fromkeys(search_terms))  # Remove duplicates while preserving order
        
        for i, term in enumerate(search_terms[:5]):  # Check up to 5 terms
            try:
                tag_query = symbols_ref.where("tags", "array_contains", term).limit(limit * 2)
                tag_results = tag_query.stream()
                
                weight = 1.0 if i == 0 else 0.8
                for doc in tag_results:
                    symbol = doc.to_dict()
                    symbol_id = doc.id
                    
                    # Avoid duplicates
                    if not any(s['id'] == symbol_id for s in matched_symbols):
                        symbol['id'] = symbol_id
                        
                        # Calculate tag position bonus - first tag gets highest score
                        tags = symbol.get('tags', [])
                        tag_position_bonus = 0
                        for pos, tag in enumerate(tags):
                            if tag.lower() == term.lower():
                                if pos == 0:
                                    tag_position_bonus = 10  # First tag gets big bonus
                                elif pos == 1:
                                    tag_position_bonus = 5   # Second tag gets medium bonus
                                elif pos <= 3:
                                    tag_position_bonus = 2   # Early tags get small bonus
                                break
                        
                        base_score = 15 * weight
                        symbol['match_score'] = base_score + tag_position_bonus
                        symbol['matched_term'] = term
                        symbol['search_phase'] = "tag_match"
                        matched_symbols.append(symbol)
            except Exception as e:
                logging.debug(f"Tag search failed for term '{term}': {e}")
        
        # Phase 3: If we still don't have results, do comprehensive fallback search.
        # Skip this expensive path for limit=1 lookups (Tap/Games single-symbol fetches)
        # to prevent timeout/abort cascades under load.
        if len(matched_symbols) == 0 and limit > 1:
            logging.info(f"No matches found for '{query_lower}', doing comprehensive search")
            try:
                # Get a larger sample for thorough matching
                all_query = symbols_ref.limit(500)  # Increased from 200
                all_results = all_query.stream()
                
                for doc in all_results:
                    symbol = doc.to_dict()
                    symbol_id = doc.id
                    
                    max_score = 0
                    best_term = query_lower
                    
                    # Comprehensive matching against all search terms
                    for term in search_terms[:3]:
                        score = 0
                        name = symbol.get('name', '').lower()
                        desc = symbol.get('description', '').lower()
                        tags = [tag.lower() for tag in symbol.get('tags', [])]
                        filename_tags = [tag.lower() for tag in symbol.get('filename_tags', [])]
                        
                        # Exact matches get high scores
                        if term == name:
                            score += 20
                        elif term in name:
                            score += 10
                            
                        if term == desc:
                            score += 15
                        elif term in desc:
                            score += 5
                        
                        # Check tags
                        if term in tags:
                            score += 12
                        if term in filename_tags:
                            score += 8
                        
                        # Check partial matches in tags
                        for tag in tags:
                            if term in tag:
                                score += 3
                        
                        if score > max_score:
                            max_score = score
                            best_term = term
                    
                    if max_score > 0:
                        symbol['id'] = symbol_id
                        symbol['match_score'] = max_score
                        symbol['matched_term'] = best_term
                        symbol['search_phase'] = "comprehensive_match"
                        matched_symbols.append(symbol)
                        
                        # Stop once we have enough good matches
                        if len(matched_symbols) >= limit * 3:
                            break
                            
            except Exception as e:
                logging.error(f"Comprehensive search failed: {e}")
        
        # Sort by match score and clean up response
        _apply_mascot_scores(matched_symbols, mascot)
        matched_symbols.sort(key=lambda x: x.get('match_score', 0), reverse=True)

        # Recursively clean non-JSON-native values (e.g., Firestore DatetimeWithNanoseconds)
        # so rare timestamp fields never crash button search responses.
        def _json_safe(value):
            if isinstance(value, dict):
                return {k: _json_safe(v) for k, v in value.items()}
            if isinstance(value, list):
                return [_json_safe(v) for v in value]
            if hasattr(value, 'isoformat'):
                try:
                    return value.isoformat()
                except Exception:
                    return str(value)
            return value

        matched_symbols = [_json_safe(symbol) for symbol in matched_symbols]
        
        search_type = "keyword_array_fast" if keyword_list else ("semantic_fast" if query_lower in semantic_mappings else "keyword_fast")
        
        # Log missing images ONLY when NO matches found across entire search
        # This includes main query, keywords, and all fallback phases.
        # Individual keywords that fail are NOT logged if other keywords/phrases succeed.
        if len(matched_symbols) == 0:
            logging.warning(f"🚨 No image found for query '{query_lower}' (with keywords: {keyword_list}) - logging to missing_images")
            await log_missing_image(query_lower)
        
        return JSONResponse(content={
            "symbols": matched_symbols[:limit],
            "total_found": len(matched_symbols),
            "query": q,
            "search_type": search_type
        })
        
    except Exception as e:
        logging.error(f"Error in fast button symbol search: {e}")
        # Fail soft for UI image lookup calls: return empty results instead of 500
        # so phrase rendering and announcements are never blocked by symbol search errors.
        return JSONResponse(content={
            "symbols": [],
            "total_found": 0,
            "query": q,
            "search_type": "button_search_error_fallback",
            "error": "Button search failed",
            "details": str(e)
        })


# Module-level in-memory cache for batch symbol lookups.
# Key: "{locale_base}:{normalized_term}" → (image_url_or_None, expires_epoch)
_batch_search_cache: dict = {}
_BATCH_SEARCH_CACHE_TTL = 300  # seconds (5 minutes)

# Module-level image URL cache shared across all profile builds.
# Key: (mascot_clean, original_label) → image_url or None
# Survives the lifetime of the server process; common AAC words hit Firestore once
# and are served from memory for every subsequent profile.
_image_url_cache: dict = {}
_IMAGE_URL_CACHE_MAX = 5000  # evict oldest half when full

# Tracks in-flight image assignment tasks to prevent duplicate concurrent runs for the
# same (account_id, aac_user_id) pair when the wizard schedules the task more than once.
_image_assign_in_flight: set = set()

# Cached admin account ID (resolved once from Firestore by email).
_admin_account_id_cache: Optional[str] = None

# In-memory master-profile image maps: mascot_clean → {label: image_url}
# Populated by _load_master_profile_image_map(); survives server lifetime.
_master_profile_image_cache: Dict[str, Dict[str, str]] = {}

MASTER_PROFILE_PREFIX = "master_"  # profile IDs under admin account: master_bobby, etc.


async def _get_admin_account_id() -> Optional[str]:
    """Return the Firestore account ID for admin@talkwithbravo.com, cached after first call."""
    global _admin_account_id_cache
    if _admin_account_id_cache:
        return _admin_account_id_cache
    if not firestore_db:
        return None
    try:
        docs = await asyncio.to_thread(
            lambda: list(
                firestore_db.collection(FIRESTORE_ACCOUNTS_COLLECTION)
                .where("email", "==", "admin@talkwithbravo.com")
                .limit(1)
                .stream()
            )
        )
        if docs:
            _admin_account_id_cache = docs[0].id
            logging.info(f"_get_admin_account_id: resolved admin account → {_admin_account_id_cache!r}")
        return _admin_account_id_cache
    except Exception as e:
        logging.warning(f"_get_admin_account_id: lookup failed: {e}")
        return None


async def _find_master_profile_user_id(admin_id: str, mascot_clean: str) -> Optional[str]:
    """
    Find the real Firestore user document ID for a master profile.

    Tries (in order):
      1. The legacy string ID used by build_master_profiles_endpoint ("master_bobby")
      2. Any user under the admin account whose display_name matches
         "master {mascot}" or "master_{mascot}" (case-insensitive, stripped).

    Returns the user_id string or None if not found.
    """
    if not firestore_db or not admin_id or not mascot_clean:
        return None

    # Fast path: legacy string user ID written by build_master_profiles_endpoint
    legacy_id = f"{MASTER_PROFILE_PREFIX}{mascot_clean}"
    try:
        legacy_cfg = await load_tap_nav_config(admin_id, legacy_id)
        if legacy_cfg and legacy_cfg.get('boards'):
            logging.info(f"_find_master_profile_user_id: found legacy id={legacy_id!r} for mascot={mascot_clean!r}")
            return legacy_id
    except Exception:
        pass

    # Scan users subcollection for a display_name matching "master {mascot}" or "master_{mascot}"
    target_names = {f"master {mascot_clean}", f"master_{mascot_clean}", mascot_clean}
    try:
        users_ref = firestore_db.collection(FIRESTORE_ACCOUNTS_COLLECTION).document(admin_id).collection(FIRESTORE_ACCOUNT_USERS_SUBCOLLECTION)
        user_docs = await asyncio.to_thread(lambda: list(users_ref.stream()))
        for doc in user_docs:
            data = doc.to_dict() or {}
            dn = str(data.get('display_name') or '').strip().lower()
            if dn in target_names:
                logging.info(
                    f"_find_master_profile_user_id: found user {doc.id!r} "
                    f"with display_name={dn!r} for mascot={mascot_clean!r}"
                )
                return doc.id
        logging.info(
            f"_find_master_profile_user_id: no user found for mascot={mascot_clean!r} "
            f"under admin_id={admin_id!r} (searched {len(user_docs)} users)"
        )
    except Exception as e:
        logging.warning(f"_find_master_profile_user_id: scan failed for {mascot_clean!r}: {e}")
    return None


async def _extract_label_map_from_config(master_config: Dict) -> Dict[str, str]:
    """Return {label: image_url} from all buttons AND boards_menu items in a tap config."""
    label_map: Dict[str, str] = {}

    for board in (master_config.get('boards') or []):
        if not isinstance(board, dict):
            continue
        for btn in (board.get('buttons') or []):
            if not isinstance(btn, dict):
                continue
            lbl = str(btn.get('label') or '').strip()
            url = str(btn.get('image_url') or '').strip()
            if lbl and url and lbl not in label_map:
                label_map[lbl] = url

    def _walk_menu(items: list) -> None:
        for item in (items or []):
            if not isinstance(item, dict):
                continue
            lbl = str(item.get('label') or '').strip()
            url = str(item.get('image_url') or '').strip()
            if lbl and url and lbl not in label_map:
                label_map[lbl] = url
            _walk_menu(item.get('children') or [])

    _walk_menu(master_config.get('boards_menu') or [])
    return label_map


async def _load_master_profile_image_map(mascot: str) -> Dict[str, str]:
    """
    Build {label: image_url} from the master profile's tap config buttons.
    Checks in-memory cache first; loads from Firestore master profile on miss.

    Searches both the legacy string user ID ("master_bobby") and any user
    under the admin account whose display_name matches "master {mascot}".
    Returns {} if no master profile with images exists.
    """
    mc = str(mascot or '').strip().lower()
    if not mc:
        return {}
    if mc in _master_profile_image_cache:
        return _master_profile_image_cache[mc]

    admin_id = await _get_admin_account_id()
    if not admin_id:
        return {}

    try:
        master_user_id = await _find_master_profile_user_id(admin_id, mc)
        if not master_user_id:
            logging.info(f"_load_master_profile_image_map: no master profile found for mascot={mc!r}")
            return {}

        master_config = await load_tap_nav_config(admin_id, master_user_id)
        if not master_config:
            logging.info(f"_load_master_profile_image_map: load_tap_nav_config returned None for user={master_user_id!r}")
            return {}

        label_map = await _extract_label_map_from_config(master_config)
        if label_map:
            _master_profile_image_cache[mc] = label_map
            logging.info(
                f"_load_master_profile_image_map: loaded {len(label_map)} label→url "
                f"entries from user={master_user_id!r} for mascot={mc!r}"
            )
        else:
            logging.warning(
                f"_load_master_profile_image_map: no buttons with image_url found in "
                f"master profile user={master_user_id!r} for mascot={mc!r} — "
                f"master profile may need image assignment (POST /api/admin/master-profiles/build)"
            )
        return label_map
    except Exception as e:
        logging.warning(f"_load_master_profile_image_map: failed for {mc!r}: {e}")
        return {}


# Pre-computed per-mascot image index for all CATEGORY_STATIC_POOLS labels.
# Loaded from Firestore on first use; eliminates bulk Firestore queries during profile creation.
# Key: mascot_clean → {original_label: image_url}
_static_image_index_cache: Dict[str, Dict[str, str]] = {}
# Labels per Firestore chunk doc — at ~200 bytes/entry, 800 entries ≈ 160 KB (safely under 1 MB).
_STATIC_IMAGE_INDEX_CHUNK_SIZE = 800


async def _load_static_image_index(mascot: str) -> Dict[str, str]:
    """Load the pre-computed static-pool image index from Firestore.

    Only trusts indexes that were built from a live aac_images query
    (build_source='live_lookup' in the metadata doc).  Indexes written
    by build_image_index.py (which uses dev-generated relative paths)
    lack this metadata and are discarded so the system rebuilds from
    the live aac_images collection automatically.
    """
    mc = str(mascot or '').strip().lower()
    if not mc:
        return {}
    if mc in _static_image_index_cache:
        return _static_image_index_cache[mc]
    if not firestore_db:
        return {}
    try:
        index_ref = firestore_db.collection('aac_image_index').document(mc)
        meta_doc = await asyncio.to_thread(index_ref.get)
        meta = (meta_doc.to_dict() or {}) if meta_doc.exists else {}
        if meta.get('build_source') != 'live_lookup':
            logging.info(
                f"_load_static_image_index: index for {mc!r} has "
                f"build_source={meta.get('build_source')!r} — discarding; will rebuild from aac_images"
            )
            return {}
        chunks_ref = index_ref.collection('chunks')
        chunk_docs = await asyncio.to_thread(lambda: list(chunks_ref.stream()))
        merged: Dict[str, str] = {}
        for doc in chunk_docs:
            chunk_map = (doc.to_dict() or {}).get('labels') or {}
            merged.update(chunk_map)
        if merged:
            _static_image_index_cache[mc] = merged
            logging.info(f"_load_static_image_index: loaded {len(merged)} entries for mascot={mc!r}")
        return merged
    except Exception as e:
        logging.warning(f"_load_static_image_index: Firestore error for {mc!r}: {e}")
        return {}


async def _save_static_image_index(mascot: str, label_map: Dict[str, str]) -> None:
    """Chunk and save the static image index to Firestore, then update the in-memory cache."""
    mc = str(mascot or '').strip().lower()
    if not firestore_db or not mc or not label_map:
        return
    try:
        meta_ref = firestore_db.collection('aac_image_index').document(mc)
        chunks_ref = meta_ref.collection('chunks')
        items = list(label_map.items())
        chunk_size = _STATIC_IMAGE_INDEX_CHUNK_SIZE
        num_chunks = (len(items) + chunk_size - 1) // chunk_size

        async def _write_chunk(idx: int, chunk_items: list) -> None:
            await asyncio.to_thread(
                lambda: chunks_ref.document(str(idx)).set({'labels': dict(chunk_items)})
            )

        await asyncio.gather(*[
            _write_chunk(i, items[start:start + chunk_size])
            for i, start in enumerate(range(0, len(items), chunk_size))
        ])
        await asyncio.to_thread(lambda: meta_ref.set({
            'mascot': mc,
            'label_count': len(label_map),
            'chunk_count': num_chunks,
            'computed_at': firestore.SERVER_TIMESTAMP,
            'build_source': 'live_lookup',  # marks this as built from live aac_images, not static file
        }))
        _static_image_index_cache[mc] = label_map
        logging.info(
            f"_save_static_image_index: saved {len(label_map)} entries "
            f"in {num_chunks} chunks for mascot={mc!r}"
        )
    except Exception as e:
        logging.warning(f"_save_static_image_index: failed for {mc!r}: {e}")


async def _build_static_image_index(mascot: str) -> Dict[str, str]:
    """Compute image URLs for every CATEGORY_STATIC_POOLS label and persist to Firestore.

    Clears both per-label and per-mascot in-memory caches before querying so that
    image updates in aac_images are always picked up fresh.
    """
    mc = str(mascot or '').strip().lower()

    # Evict any stale entries from the per-label cache for this mascot so that
    # changed images in aac_images are fetched fresh from Firestore.
    stale_keys = [k for k in _image_url_cache if k[0] == mc]
    for k in stale_keys:
        del _image_url_cache[k]
    _static_image_index_cache.pop(mc, None)

    all_pool_labels: List[str] = []
    for words in CATEGORY_STATIC_POOLS.values():
        all_pool_labels.extend(str(w).strip() for w in words if str(w).strip())
    unique_labels = list(dict.fromkeys(all_pool_labels))
    logging.info(
        f"_build_static_image_index: resolving {len(unique_labels)} unique "
        f"pool labels for mascot={mc!r} (caches cleared)"
    )
    label_to_url = await _lookup_images_for_labels(
        unique_labels, mc, '', '', source='static_image_index'
    )
    await _save_static_image_index(mc, label_to_url)
    return label_to_url


async def _ensure_static_image_index(mascot: str) -> Dict[str, str]:
    """Return the static image index for the given mascot.

    Priority order:
      1. In-memory cache — zero cost.
      2. Firestore aac_image_index — compact label→URL map written by build_master_profiles_endpoint.
      3. Master profile tap config — read directly and save to aac_image_index for future calls.
         URLs come from the master profile's own image_url fields, which were resolved against
         this environment's aac_images collection, so they are guaranteed valid for this bucket.
      4. Committed Python file (STATIC_IMAGE_ASSIGNMENTS) — last-resort fallback; dev-generated
         paths may not exist in test/prod bucket.
      5. Built from scratch via _lookup_images_for_labels — slow, one-time per mascot.
    """
    mc = str(mascot or '').strip().lower()
    if not mc:
        return {}

    # 1. In-memory cache
    if mc in _static_image_index_cache:
        return _static_image_index_cache[mc]

    # 2. Firestore aac_image_index — fast compact cache populated by master profile build.
    idx = await _load_static_image_index(mc)
    if idx:
        return idx

    # 3. Master profile — load button image_urls directly.  These are env-specific URLs
    #    because build_master_profiles_endpoint resolves them against the live aac_images
    #    collection in this environment.  Save the result to aac_image_index so step 2
    #    wins on all future calls.
    master_idx = await _load_master_profile_image_map(mc)
    if master_idx:
        logging.info(
            f"_ensure_static_image_index: loaded {len(master_idx)} entries "
            f"from master profile for mascot={mc!r}; saving to aac_image_index"
        )
        await _save_static_image_index(mc, master_idx)
        return master_idx

    # 4. Committed Python file — zero I/O fallback when neither index nor master profile
    #    is available (first deploy or mascot not yet in master profiles).
    file_paths = STATIC_IMAGE_ASSIGNMENTS.get(mc) or {}
    if file_paths and AAC_IMAGES_BUCKET_NAME:
        base = f"https://storage.googleapis.com/{AAC_IMAGES_BUCKET_NAME}/"
        resolved = {label: base + path for label, path in file_paths.items() if path}
        if resolved:
            _static_image_index_cache[mc] = resolved
            logging.info(
                f"_ensure_static_image_index: loaded {len(resolved)} entries "
                f"from static_image_assignments.py for mascot={mc!r}"
            )
            return resolved

    # 5. Build from scratch (no master profile and no static file for this mascot)
    return await _build_static_image_index(mc)


def _make_pool_button_entry(
    pool_idx: int,
    word: str,
    board_id: str,
    is_overflow: bool,
    grid_cols: int,
    default_button_action: str,
) -> Dict[str, Any]:
    """Create a single static pool button dict (shared between regenerate_boards and backfill)."""
    variants = WORD_VARIANTS.get(str(word).strip().lower(), {})
    btn: Dict[str, Any] = {
        'id': f"btn_{board_id}_pool_{pool_idx}",
        'label': word,
        'background_color': '#FFFFFF',
        'text_color': '#000000',
        'after_selection': default_button_action,
        'button_type': 'static',
        'pool_index': pool_idx,
    }
    if is_overflow:
        btn['row'] = None
        btn['col'] = None
    else:
        btn['row'] = pool_idx // grid_cols
        btn['col'] = pool_idx % grid_cols
    if variants.get('past_tense'):
        btn['past_tense'] = variants['past_tense']
    if variants.get('plural'):
        btn['plural'] = variants['plural']
    return btn


def _pool_key(s: str) -> str:
    k = ''.join(ch if ch.isalnum() else '_' for ch in str(s or '').strip().lower())
    while '__' in k:
        k = k.replace('__', '_')
    return k.strip('_')


async def _lookup_images_for_labels(
    labels: List[str],
    mascot: str = '',
    account_id: str = '',
    aac_user_id: str = '',
    source: str = '',
) -> Dict[str, str]:
    """
    Batch-look up the best symbol image for each label string.
    Returns {original_label: image_url}. Missing results are omitted.
    Logs unresolved labels to the missing_images collection with the given source.
    Shared by board generation, assign-all-images endpoint, and board builder.
    """
    import re as _re

    if not labels or not firestore_db:
        return {}

    def _norm(s: str) -> str:
        return ' '.join(_re.sub(r'[^a-z0-9]+', ' ', str(s or '').strip().lower()).split())

    # Stop words stripped from the START of a phrase to extract the key searchable term.
    # e.g. "to go"→"go", "a drink"→"drink", "I want"→"want", "I'm thinking"→"thinking".
    # Negators ("not") are intentionally excluded so negation is preserved.
    # Contraction residuals: _norm() strips apostrophes, so "I'm"→"i m", "we're"→"we re".
    _LEAD_STOPS = frozenset({
        # Articles
        'a', 'an', 'the',
        # Conjunctions
        'and', 'or', 'but',
        # Prepositions / particles
        'to', 'in', 'on', 'at', 'for', 'with', 'of', 'by', 'from', 'into', 'about', 'up', 'out',
        'since', 'after', 'before', 'until', 'while', 'when', 'because', 'like', 'than', 'though', 'as',
        # Possessive adjectives / intensifiers
        'my', 'your', 'his', 'her', 'its', 'our', 'their', 'own',
        # Quantifiers / demonstratives acting as articles
        'some', 'any', 'this', 'that', 'these', 'those',
        # Subject pronouns — e.g. "I want", "we can", "you need"
        'i', 'we', 'you', 'he', 'she', 'they', 'it',
        # Contraction residuals after _norm strips apostrophes:
        # "I'm"→"i m", "we're"→"we re", "I've"→"i ve", "I'll"→"i ll", "I'd"→"i d", "he's"→"he s"
        'm', 're', 've', 'll', 'd', 's',
        # All forms of "to be" — "is coming"→"coming", "was playing"→"playing",
        # "will be going"→"going", "have been eating"→"eating"
        'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
        # Modal / auxiliary verbs that precede the content word
        'will', 'would', 'shall', 'should',
        'can', 'could', 'may', 'might', 'must',
        'have', 'has', 'had', 'do', 'does', 'did',
        # Common leading content verbs whose object is the true key term:
        # "want a hug"→"hug", "need a drink"→"drink", "want to dance"→"dance",
        # "need to go to the store"→"store", "love to swim"→"swim",
        # "feel like crying"→"crying", "get some water"→"water",
        # "let me try"→"try", "try to relax"→"relax"
        'want', 'need', 'love', 'feel', 'get', 'let', 'try', 'feeling',
        'look', 'looks', 'looked', 'looking', 'wants', 'needs',
        # Degree / intensifier adverbs — "so mad"→"mad", "very upset"→"upset",
        # "really frustrated"→"frustrated", "kind of sad"→"of sad"→"sad"
        # "easy" included so "it easy boss"→"boss", "it easy dad"→"dad"
        'so', 'very', 'really', 'quite', 'pretty', 'too',
        'extremely', 'super', 'totally', 'just', 'kind', 'sort', 'easy',
        # Greeting/address prefixes — "there, boss"→"boss", "doing, dad"→"dad"
        'there', 'doing', 'go', 'something', 'somewhere',
        # Question words — "what you are watching"→"watching", "what's wrong"→"wrong"
        'what', 'how',
        # Temporal connectives — "then, at home"→norm→"then at home"→"home"
        'then',
        # Directional prepositions — "towards the park"→"park", "down, the street"→"street"
        'towards', 'down', 'going',
        # Conditional conjunction — "if you want"→"want"
        'if',
        # Reporting verb — "said he was hungry"→"hungry"
        'said',
    })

    # Words that appear at the END of a label but don't contribute to the image key term.
    # Stripped iteratively from the tail so "ball is this" → "ball is" → "ball",
    # "book is that" → "book is" → "book", "playing now" → "playing".
    _TRAIL_STOPS = frozenset({
        # Articles dangling at the end: "open the" → "open", "eat a" → "eat"
        'a', 'an', 'the','be'
        # Prepositions that trail without adding meaning to the key concept.
        # "on", "in", "out", "up" are intentionally excluded — they form phrasal
        # verbs ("turn on", "log in", "go out", "wake up") and must be preserved.
        'at', 'of', 'to', 'for', 'with', 'by',
        # Demonstrative pronouns used as sentence-final deictic ("ball is this", "want that")
        'this', 'that', 'these', 'those',
        # "To be" forms at the tail ("ball is this" → after "this" stripped → "ball is")
        'is', 'are', 'was', 'were',
        # Temporal/aspectual adverbs
        'now', 'later', 'soon',
        'today', 'tomorrow', 'tonight', 'yesterday',
        'already', 'again', 'still', 'yet', 'then', 'next',
        # Polite single-word trailing fillers added by LLM: "can I have water please"
        'please',
    })

    # Multi-word trailing phrases stripped as a unit before single-word stop processing.
    # Each entry is a tuple of normalized words to match at the END of a phrase.
    # Only stripped when content words remain after removal.
    # e.g. "I want water thank you" → strip ('thank','you') → "I want water"
    _TRAIL_PHRASES = [
        ('thank', 'you'),
        ('thank', 'you', 'so', 'much'),
        ('if', 'you', 'please'),
        ('if', 'you', 'don', 't', 'mind'),
        
    ]

    # Multi-word leading phrases stripped as a unit before single-word stop processing.
    # Each entry is a tuple of normalized words to match at the start of a phrase.
    # Only stripped when content words remain after removal.
    # e.g. "it easy boss" → strip ('it','easy') → "boss"
    _LEAD_PHRASES = [
        ('it', 'easy'),
    ]

    def _key_term(norm: str) -> str:
        words = norm.split()
        # Strip known multi-word leading phrases first
        for ph in _LEAD_PHRASES:
            n = len(ph)
            while len(words) > n and words[:n] == list(ph):
                words = words[n:]
        # Strip single-word lead stops, but never strip an auxiliary/modal that is
        # immediately followed by "t" — that is the negation residual left by _norm
        # stripping the apostrophe from "can't", "couldn't", etc.
        # "can t stop" → keep "can t" intact so negation is preserved.
        # "can I have water" → "can" is followed by "i", not "t", so it strips normally.
        while len(words) > 1 and words[0] in _LEAD_STOPS:
            if len(words) >= 2 and words[1] == 't':
                break
            words = words[1:]
        # Strip multi-word trailing phrases before single-word trail stops
        changed = True
        while changed and len(words) > 1:
            changed = False
            for ph in _TRAIL_PHRASES:
                n = len(ph)
                if len(words) > n and words[-n:] == list(ph):
                    words = words[:-n]
                    changed = True
                    break
        while len(words) > 1 and words[-1] in _TRAIL_STOPS:
            words = words[:-1]
        return ' '.join(words)

    # Inflected verb form → base (infinitive) for lemma-based image matching.
    # Lets "telling" / "told" find an image whose subconcept is "tell".
    # Irregular verbs are listed explicitly; regular -ing / -ed / -s handled below.
    _VERB_BASES: Dict[str, str] = {
        # be
        'am':'be','is':'be','are':'be','was':'be','were':'be','been':'be','being':'be',
        # eat / drink / cook
        'ate':'eat','eaten':'eat','eating':'eat','eats':'eat',
        'drank':'drink','drunk':'drink','drinking':'drink','drinks':'drink',
        # go / come / run
        'went':'go','gone':'go','going':'go','goes':'go',
        'came':'come','coming':'come','comes':'come',
        'ran':'run','running':'run','runs':'run',
        # say / tell / speak / ask
        'said':'say','saying':'say','says':'say',
        'told':'tell','telling':'tell','tells':'tell',
        'spoke':'speak','spoken':'speak','speaking':'speak','speaks':'speak',
        'asked':'ask','asking':'ask','asks':'ask',
        # see / look / watch / hear / feel
        'saw':'see','seen':'see','seeing':'see','sees':'see',
        'looked':'look','looking':'look','looks':'look',
        'watched':'watch','watching':'watch','watches':'watch',
        'heard':'hear','hearing':'hear','hears':'hear',
        'felt':'feel','feeling':'feel','feels':'feel',
        # give / take / make / get / put / set / let / cut / hit / put
        'gave':'give','given':'give','giving':'give','gives':'give',
        'took':'take','taken':'take','taking':'take','takes':'take',
        'made':'make','making':'make','makes':'make',
        'got':'get','gotten':'get','getting':'get','gets':'get',
        'put':'put','putting':'put','puts':'put',
        'set':'set','setting':'set','sets':'set',
        'let':'let','letting':'let','lets':'let',
        'cut':'cut','cutting':'cut','cuts':'cut',
        'hit':'hit','hitting':'hit','hits':'hit',
        'hurt':'hurt','hurting':'hurt','hurts':'hurt',
        'read':'read','reading':'read','reads':'read',
        # know / think / mean / find / lose / keep / leave / bring / buy
        'knew':'know','known':'know','knowing':'know','knows':'know',
        'thought':'think','thinking':'think','thinks':'think',
        'meant':'mean','meaning':'mean','means':'mean',
        'found':'find','finding':'find','finds':'find',
        'lost':'lose','losing':'lose','loses':'lose',
        'kept':'keep','keeping':'keep','keeps':'keep',
        'left':'leave','leaving':'leave','leaves':'leave',
        'brought':'bring','bringing':'bring','brings':'bring',
        'bought':'buy','buying':'buy','buys':'buy',
        # write / draw / sing / play / swim / throw / fly / ride / drive
        'wrote':'write','written':'write','writing':'write','writes':'write',
        'drew':'draw','drawn':'draw','drawing':'draw','draws':'draw',
        'sang':'sing','sung':'sing','singing':'sing','sings':'sing',
        'swam':'swim','swum':'swim','swimming':'swim','swims':'swim',
        'threw':'throw','thrown':'throw','throwing':'throw','throws':'throw',
        'flew':'fly','flown':'fly','flying':'fly','flies':'fly',
        'rode':'ride','ridden':'ride','riding':'ride','rides':'ride',
        'drove':'drive','driven':'drive','driving':'drive','drives':'drive',
        # fall / stand / sit / sleep / wake / hold / send / meet / pay
        'fell':'fall','fallen':'fall','falling':'fall','falls':'fall',
        'stood':'stand','standing':'stand','stands':'stand',
        'sat':'sit','sitting':'sit','sits':'sit',
        'slept':'sleep','sleeping':'sleep','sleeps':'sleep',
        'woke':'wake','woken':'wake','waking':'wake','wakes':'wake',
        'held':'hold','holding':'hold','holds':'hold',
        'sent':'send','sending':'send','sends':'send',
        'met':'meet','meeting':'meet','meets':'meet',
        'paid':'pay','paying':'pay','pays':'pay',
        # teach / catch / build / fight / win / wear / break / choose / lead / feed
        'taught':'teach','teaching':'teach','teaches':'teach',
        'caught':'catch','catching':'catch','catches':'catch',
        'built':'build','building':'build','builds':'build',
        'fought':'fight','fighting':'fight','fights':'fight',
        'won':'win','winning':'win','wins':'win',
        'wore':'wear','worn':'wear','wearing':'wear','wears':'wear',
        'broke':'break','broken':'break','breaking':'break','breaks':'break',
        'chose':'choose','chosen':'choose','choosing':'choose','chooses':'choose',
        'led':'lead','leading':'lead','leads':'lead',
        'fed':'feed','feeding':'feed','feeds':'feed',
        # misc common AAC verbs
        'spent':'spend','spending':'spend','spends':'spend',
        'grew':'grow','grown':'grow','growing':'grow','grows':'grow',
        'blew':'blow','blown':'blow','blowing':'blow','blows':'blow',
        'began':'begin','begun':'begin','beginning':'begin','begins':'begin',
        'rang':'ring','rung':'ring','ringing':'ring','rings':'ring',
        'forgot':'forget','forgotten':'forget','forgetting':'forget','forgets':'forget',
        'froze':'freeze','frozen':'freeze','freezing':'freeze','freezes':'freeze',
        'bit':'bite','bitten':'bite','biting':'bite','bites':'bite',
        'hid':'hide','hidden':'hide','hiding':'hide','hides':'hide',
        'laid':'lay','laying':'lay','lays':'lay',
        'lit':'light','lighting':'light','lights':'light',
        'shook':'shake','shaken':'shake','shaking':'shake','shakes':'shake',
        'slid':'slide','sliding':'slide','slides':'slide',
        'spun':'spin','spinning':'spin','spins':'spin',
        'stuck':'stick','sticking':'stick','sticks':'stick',
        'swore':'swear','sworn':'swear','swearing':'swear','swears':'swear',
        'swung':'swing','swinging':'swing','swings':'swing',
        'tore':'tear','torn':'tear','tearing':'tear','tears':'tear',
        'understood':'understand','understanding':'understand','understands':'understand',
        'wept':'weep','weeping':'weep','weeps':'weep',
        'swept':'sweep','sweeping':'sweep','sweeps':'sweep',
        'stole':'steal','stolen':'steal','stealing':'steal','steals':'steal',
        'dug':'dig','digging':'dig','digs':'dig',
        'bent':'bend','bending':'bend','bends':'bend',
        'bled':'bleed','bleeding':'bleed','bleeds':'bleed',
        'rode':'ride','ridden':'ride','riding':'ride','rides':'ride',
        'rose':'rise','risen':'rise','rising':'rise','rises':'rise',
        # regular verbs with irregular spelling that suffix rules would get wrong
        'cried':'cry','crying':'cry','cries':'cry',
        'tried':'try','trying':'try','tries':'try',
        'played':'play','playing':'play','plays':'play',
        'walked':'walk','walking':'walk','walks':'walk',
        'talked':'talk','talking':'talk','talks':'talk',
        'jumped':'jump','jumping':'jump','jumps':'jump',
        'laughed':'laugh','laughing':'laugh','laughs':'laugh',
        'helped':'help','helping':'help','helps':'help',
        'wanted':'want','wanting':'want','wants':'want',
        'needed':'need','needing':'need','needs':'need',
        'liked':'like','liking':'like','likes':'like',
        'loved':'love','loving':'love','loves':'love',
        'hugged':'hug','hugging':'hug','hugs':'hug',
        'kissed':'kiss','kissing':'kiss','kisses':'kiss',
        'smiled':'smile','smiling':'smile','smiles':'smile',
        'waved':'wave','waving':'wave','waves':'wave',
        'danced':'dance','dancing':'dance','dances':'dance',
        'painted':'paint','painting':'paint','paints':'paint',
        'opened':'open','opening':'open','opens':'open',
        'closed':'close','closing':'close','closes':'close',
        'stopped':'stop','stopping':'stop','stops':'stop',
        'started':'start','starting':'start','starts':'start',
        'finished':'finish','finishing':'finish','finishes':'finish',
        'cleaned':'clean','cleaning':'clean','cleans':'clean',
        'cooked':'cook','cooking':'cook','cooks':'cook',
        'pushed':'push','pushing':'push','pushes':'push',
        'pulled':'pull','pulling':'pull','pulls':'pull',
        'worked':'work','working':'work','works':'work',
        'waited':'wait','waiting':'wait','waits':'wait',
        'shared':'share','sharing':'share','shares':'share',
        'turned':'turn','turning':'turn','turns':'turn',
        'moved':'move','moving':'move','moves':'move',
        'kicked':'kick','kicking':'kick','kicks':'kick',
        'climbed':'climb','climbing':'climb','climbs':'climb',
        'called':'call','calling':'call','calls':'call',
        'visited':'visit','visiting':'visit','visits':'visit',
        'learned':'learn','learning':'learn','learns':'learn',
        'showed':'show','showing':'show','shows':'show','shown':'show',
        'spelled':'spell','spelling':'spell','spells':'spell',
    }

    def _verb_base(word: str) -> str:
        """Return base (infinitive) form of a single word, or '' if not applicable."""
        if not word or ' ' in word:   # only single words
            return ''
        base = _VERB_BASES.get(word)
        if base and base != word:
            return base
        # Conservative suffix rules for regular verbs not in the table.
        # -ies → -y  (cries→cry, already in table but safe)
        if word.endswith('ies') and len(word) > 4:
            return word[:-3] + 'y'
        # -s (but not -ss, -ies already handled)
        if word.endswith('s') and not word.endswith('ss') and len(word) > 3:
            return word[:-1]
        return ''

    mascot_clean = str(mascot or '').strip().lower()
    unique_labels = list(dict.fromkeys(labels))  # preserve order, dedupe

    # Fast path: serve any label already in the process-level image cache.
    label_to_url: Dict[str, str] = {}
    cache_hits: set = set()
    for lbl in unique_labels:
        cached_val = _image_url_cache.get((mascot_clean, lbl))
        if cached_val is not None:  # None → cached miss; not in dict → unknown
            if cached_val:  # non-empty string means a real URL was found
                label_to_url[lbl] = cached_val
            cache_hits.add(lbl)

    uncached_labels = [lbl for lbl in unique_labels if lbl not in cache_hits]
    if not uncached_labels:
        logging.debug(f"_lookup_images_for_labels: all {len(unique_labels)} labels served from cache (mascot={mascot_clean!r})")
        return label_to_url

    # Continue with Firestore queries only for labels not in the cache.
    unique_labels = uncached_labels

    norm_map = {lbl: _norm(lbl) for lbl in unique_labels}  # label → normalized
    key_term_map = {lbl: _key_term(norm_map[lbl]) for lbl in unique_labels if norm_map.get(lbl)}

    # Verb-base map: for each label, the base form of the key term (or norm label).
    # e.g. "telling" → "tell", "told" → "tell", "is telling" → (key_term "telling") → "tell"
    def _label_verb_base(lbl: str) -> str:
        kt = key_term_map.get(lbl, '')
        norm = norm_map.get(lbl, '')
        # Prefer base of key_term; fall back to base of full norm label
        candidate = kt if (kt and kt != norm) else norm
        # Only apply to single-word candidates
        return _verb_base(candidate) if candidate and ' ' not in candidate else ''

    verb_base_map = {lbl: _label_verb_base(lbl) for lbl in unique_labels}

    # Include key terms in the query set so images keyed by the stripped term are fetched.
    all_norm = set(v for v in norm_map.values() if v)
    all_norm |= {kt for kt in key_term_map.values() if kt}
    all_norm |= {vb for vb in verb_base_map.values() if vb}

    # For labels containing an apostrophe, also search the normalized spaced form
    # (apostrophe → space, then _norm rules) so images whose subconcept is stored
    # with an apostrophe (e.g. "ma'am", "don't want") are found.
    # norm_map already produces the spaced form, so this is already in all_norm —
    # the block below is a no-op for most cases but ensures multi-word apostrophe
    # labels (e.g. "don't want to") produce the right intermediate forms too.
    import re as _re2
    for lbl in unique_labels:
        if "'" in lbl or "'" in lbl:  # straight and curly apostrophe
            spaced = _re2.sub(r"[''']", ' ', lbl.lower())
            spaced_norm = ' '.join(_re2.sub(r'[^a-z0-9]+', ' ', spaced).split())
            if spaced_norm:
                all_norm.add(spaced_norm)

    if not all_norm:
        return {}

    images_ref = firestore_db.collection("aac_images")

    def _chunked(seq, n=10):
        seq = list(seq)
        for i in range(0, len(seq), n):
            yield seq[i:i + n]

    def _stream(q):
        return list(q.stream())

    # Build parallel queries mirroring batch-search: subconcept/concept (exact), search_terms, tags.
    # "global" source is queried separately — mascot-specific assets (bobby/bonnie/buddy) live there.
    _ACCEPTED_SOURCES = {"bravo_images", "global"}
    queries = []
    for chunk in _chunked(all_norm, 10):
        queries.append(("subconcept",        images_ref.where("source", "==", "bravo_images").where("subconcept", "in", chunk).limit(100)))
        queries.append(("subconcept_global", images_ref.where("source", "==", "global").where("subconcept", "in", chunk).limit(100)))
        queries.append(("concept",           images_ref.where("source", "==", "bravo_images").where("concept", "in", chunk).limit(100)))
        queries.append(("concept_global",    images_ref.where("source", "==", "global").where("concept", "in", chunk).limit(100)))
        queries.append(("search_terms",      images_ref.where("search_terms", "array_contains_any", chunk).limit(300)))
        queries.append(("tags_legacy",       images_ref.where("source", "==", "bravo_images").where("tags", "array_contains_any", chunk).limit(250)))
        queries.append(("tags_global",       images_ref.where("source", "==", "global").where("tags", "array_contains_any", chunk).limit(250)))

    # Run in small batches to avoid saturating the shared ThreadPoolExecutor and
    # blocking unrelated Firestore operations on other in-flight requests.
    _BATCH = 30
    streams: List[Any] = []
    try:
        asyncio.get_running_loop()
        for _i in range(0, len(queries), _BATCH):
            _batch = queries[_i: _i + _BATCH]
            _results = await asyncio.gather(
                *[asyncio.to_thread(_stream, q) for _, q in _batch],
                return_exceptions=True,
            )
            streams.extend(_results)
    except RuntimeError:
        streams = [_stream(q) for _, q in queries]

    # Index candidates by doc id.
    # search_terms query has no source filter — only keep accepted sources in code.
    candidate_docs: Dict[str, dict] = {}
    for (qtype, _), result in zip(queries, streams):
        if isinstance(result, Exception):
            continue
        for doc in result:
            data = doc.to_dict() or {}
            if not data.get("image_url"):
                continue
            if qtype == "search_terms" and data.get("source") not in _ACCEPTED_SOURCES:
                continue
            candidate_docs[doc.id] = data

    # Load custom images (mascot-specific assets live here)
    custom_candidates: List[dict] = []
    if account_id and aac_user_id:
        try:
            custom_ref = (firestore_db.collection("accounts").document(account_id)
                          .collection("profiles").document(aac_user_id)
                          .collection("custom_images"))
            for doc in (await asyncio.to_thread(lambda: list(custom_ref.where("active", "==", True).limit(500).stream()))):
                d = doc.to_dict() or {}
                if d.get("image_url"):
                    custom_candidates.append({
                        "id": doc.id,
                        "url": d["image_url"],
                        "subconcept": _norm(d.get("subconcept") or ""),
                        "concept":    _norm(d.get("concept") or ""),
                        "tags":       [_norm(t) for t in (d.get("tags") or []) if _norm(t)],
                        "mascot":     str(d.get("mascot") or "").strip().lower(),
                    })
        except Exception as _ce:
            logging.debug(f"_lookup_images_for_labels: custom image load failed: {_ce}")

    # Pre-normalize candidate data once so _score doesn't redo it per label.
    processed: List[dict] = []
    for doc_id, data in candidate_docs.items():
        url = data.get("image_url")
        if not url:
            continue
        sub = _norm(data.get("subconcept") or "")
        con = _norm(data.get("concept") or "")
        tags = [_norm(t) for t in (data.get("tags") or []) if t]
        st   = [_norm(t) for t in (data.get("search_terms") or []) if t] if isinstance(data.get("search_terms"), list) else []
        all_terms = set(tags + st + [sub, con]) - {''}
        processed.append({
            "url": url,
            "sub": sub,
            "con": con,
            "all_terms": all_terms,
            "mascot": str(data.get("mascot") or "").strip().lower(),
        })

    for cc in custom_candidates:
        url = cc.get("url")
        if not url:
            continue
        sub = cc.get("subconcept") or ""
        con = cc.get("concept") or ""
        tags = cc.get("tags") or []
        all_terms = set(tags + [sub, con]) - {''}
        processed.append({
            "url": url,
            "sub": sub,
            "con": con,
            "all_terms": all_terms,
            "mascot": cc.get("mascot") or "",
        })

    def _score(norm_label: str, cand: dict, key_term: str = '', verb_base: str = '') -> int:
        # Negation mismatch guard: a positive label must not match a negative image and vice versa.
        label_neg = norm_label.startswith('not ')
        cand_neg = (
            cand["sub"].startswith('not ')
            or cand["con"].startswith('not ')
            or any(t.startswith('not ') for t in cand["all_terms"])
        )
        if label_neg != cand_neg:
            return -9999

        # Tier-based scoring for text quality (high→low):
        #   1. Exact subconcept match  (10000)
        #   2. Exact concept match     (9000)
        #   3. Key-term subconcept     (8000)  — leading stops stripped, e.g. "to go" → "go"
        #   4. Key-term concept        (7000)
        #   5. Full-label tag match    (5000)
        #   6. Key-term tag match      (3500)
        #
        # Mascot adjustment is large (+5000 correct / -1000 no mascot / -5000 wrong) so that
        # a correct-mascot image at any text tier beats a no-mascot or wrong-mascot image at
        # the next text tier up. E.g. Bobby "action" tag match (5000+5000=10000) beats a
        # generic "hug" image whose concept is "actions" (9000-1000=8000).
        score = 0
        if norm_label == cand["sub"]:
            score += 10000
        elif norm_label == cand["con"]:
            score += 9000
        elif key_term and key_term != norm_label and key_term == cand["sub"]:
            score += 8000
        elif key_term and key_term != norm_label and key_term == cand["con"]:
            score += 7000
        elif norm_label in cand["all_terms"]:
            # If we extracted a key term, a match on the full label (e.g. "with ice" matching
            # the "with" image's tags) is misleading — the stop word is driving the match, not
            # the content word. Reject it so the button stays unassigned rather than getting
            # the wrong image. Only allow full-label tag matches when no key term was extracted.
            if key_term and key_term != norm_label:
                return -9999
            score += 5000
        elif key_term and key_term != norm_label and key_term in cand["all_terms"]:
            score += 3500
        elif verb_base and verb_base != norm_label and verb_base != key_term and verb_base == cand["sub"]:
            # Tier 2500: inflected verb form matches image subconcept via lemma
            # e.g. "telling" / "told" → base "tell" == subconcept "tell"
            score += 2500
        elif verb_base and verb_base != norm_label and verb_base != key_term and verb_base == cand["con"]:
            score += 2000
        elif verb_base and verb_base != norm_label and verb_base != key_term and verb_base in cand["all_terms"]:
            score += 1500
        else:
            return -9999  # no textual match at all

        if mascot_clean:
            img_m = cand["mascot"]
            if img_m == mascot_clean:
                score += 5000   # correct mascot: strong preference, can cross text tiers
            elif img_m and img_m != mascot_clean:
                score -= 5000   # wrong mascot: strongly penalized
            else:
                score -= 1000   # no mascot when user has one: mild penalty vs correct-mascot image
        return score

    # Score all pre-processed candidates for each uncached label.
    # label_to_url was pre-populated with cache hits above; merge new results in.
    newly_resolved: Dict[str, str] = {}
    for lbl in unique_labels:
        norm_lbl = norm_map.get(lbl, '')
        if not norm_lbl:
            continue
        kt = key_term_map.get(lbl, '')
        key_term = kt if kt != norm_lbl else ''  # only pass if stripping actually changed it
        vb = verb_base_map.get(lbl, '')
        verb_base = vb if vb and vb != norm_lbl and vb != key_term else ''
        best_score = 0  # require a genuine textual match (score > 0)
        best_url = None

        for cand in processed:
            s = _score(norm_lbl, cand, key_term, verb_base)
            if s > best_score:
                best_score = s
                best_url = cand["url"]

        if best_url:
            newly_resolved[lbl] = best_url

    label_to_url.update(newly_resolved)

    logging.info(f"_lookup_images_for_labels: {len(newly_resolved)}/{len(unique_labels)} new labels resolved from Firestore, {len(cache_hits)} from cache (mascot={mascot_clean!r}, source={source!r})")

    # Populate the process-level cache with results for this batch.
    # Cache both hits (url string) and misses (empty string) so repeated lookups
    # of unresolved labels skip Firestore too.
    if len(_image_url_cache) >= _IMAGE_URL_CACHE_MAX:
        # Evict the oldest half by reinserting only the newer half.
        items = list(_image_url_cache.items())
        _image_url_cache.clear()
        for k, v in items[len(items) // 2:]:
            _image_url_cache[k] = v
    for lbl in unique_labels:
        _image_url_cache[(mascot_clean, lbl)] = newly_resolved.get(lbl, '')

    # Log any labels that had no matching image so admins can track gaps.
    # Only log for labels queried in this call (not cache hits — those were already logged).
    # Skip pure numbers — they display as text and are not expected to have images.
    missing_labels = [
        lbl for lbl in unique_labels
        if lbl not in newly_resolved and not _norm(lbl).replace(' ', '').isdigit()
    ]
    if missing_labels:
        context = {"source": source, "mascot": mascot_clean, "account_id": account_id, "aac_user_id": aac_user_id}
        for lbl in missing_labels:
            asyncio.create_task(log_missing_image(lbl, context))

    return label_to_url


async def _build_custom_image_term_map(account_id: str, aac_user_id: str) -> Dict[str, str]:
    """
    Loads all active custom images (including profile image) for a user and returns
    a dict of normalized_term → image_url. Newest custom image wins per term.
    """
    import re as _re
    def _norm(s: str) -> str:
        return ' '.join(_re.sub(r'[^a-z0-9]+', ' ', str(s or '').strip().lower()).split())

    if not firestore_db:
        return {}
    try:
        custom_ref = (firestore_db.collection("accounts").document(account_id)
                                  .collection("profiles").document(aac_user_id)
                                  .collection("custom_images"))
        docs = list(custom_ref.where("active", "==", True).stream())
    except Exception as e:
        logging.warning(f"_build_custom_image_term_map Firestore error for {account_id}/{aac_user_id}: {e}")
        return {}

    # Sort oldest → newest so the newest URL wins when terms overlap
    docs.sort(key=lambda d: (d.to_dict().get('created_at') or 0))

    term_map: Dict[str, str] = {}
    for doc in docs:
        data = doc.to_dict()
        url = str(data.get('image_url') or '').strip()
        if not url:
            continue
        for field in ('subconcept', 'concept'):
            val = _norm(data.get(field) or '')
            if val:
                term_map[val] = url
        for tag in (data.get('tags') or []):
            t = _norm(tag)
            if t:
                term_map[t] = url
    return term_map


async def _apply_custom_images_to_tap_config(account_id: str, aac_user_id: str) -> None:
    """
    Applies custom images (profile + uploaded) to matching static buttons in the tap config.
    Called after any custom image save, update, or delete. Custom images take priority
    over bravo_images assignments. Buttons that had a custom image URL but no longer
    match any active custom image are re-queried from bravo_images.
    """
    import re as _re
    def _norm(s: str) -> str:
        return ' '.join(_re.sub(r'[^a-z0-9]+', ' ', str(s or '').strip().lower()).split())
    def _is_custom_url(url: str) -> bool:
        return bool(url and '/custom_images/' in url)

    term_map = await _build_custom_image_term_map(account_id, aac_user_id)
    config = await load_tap_nav_config(account_id, aac_user_id)
    if not config:
        return

    changed = False
    fallback_labels: List[str] = []

    def _process(item: dict) -> None:
        nonlocal changed
        label = str(item.get('label') or '').strip()
        if not label:
            return
        lbl_norm = _norm(label)
        if lbl_norm in term_map:
            new_url = term_map[lbl_norm]
            if item.get('image_url') != new_url:
                item['image_url'] = new_url
                changed = True
        elif _is_custom_url(item.get('image_url') or ''):
            # Had a custom image that no longer matches — clear and re-query bravo_images
            item['image_url'] = None
            fallback_labels.append(label)
            changed = True

    for board in (config.get('boards') or []):
        if isinstance(board, dict):
            for btn in (board.get('buttons') or []):
                if isinstance(btn, dict):
                    _process(btn)

    def _walk_menu(items: list) -> None:
        for item in (items or []):
            if isinstance(item, dict):
                _process(item)
                _walk_menu(item.get('children') or [])
    _walk_menu(config.get('boards_menu') or [])

    if not changed:
        return

    # Re-query bravo_images for buttons that lost their custom image assignment
    if fallback_labels:
        try:
            settings = await load_settings_from_file(account_id, aac_user_id)
            mascot = str(settings.get('mascot') or '').strip().lower()
            fallback_map = await _lookup_images_for_labels(
                fallback_labels, mascot, account_id, aac_user_id, source="custom_img_fallback"
            )
            def _apply_fb(item: dict) -> None:
                if item.get('image_url') is None:
                    url = fallback_map.get(str(item.get('label') or '').strip())
                    if url:
                        item['image_url'] = url
            for board in (config.get('boards') or []):
                if isinstance(board, dict):
                    for btn in (board.get('buttons') or []):
                        if isinstance(btn, dict):
                            _apply_fb(btn)
            def _walk_fb(items: list) -> None:
                for item in (items or []):
                    if isinstance(item, dict):
                        _apply_fb(item)
                        _walk_fb(item.get('children') or [])
            _walk_fb(config.get('boards_menu') or [])
        except Exception as e:
            logging.warning(f"Bravo fallback lookup failed for {account_id}/{aac_user_id}: {e}")

    config['buttons'] = compose_legacy_buttons_from_boards_menu(config)
    await save_tap_nav_config(account_id, aac_user_id, config)
    logging.info(
        f"✅ Custom images applied to tap config {account_id}/{aac_user_id}: "
        f"{len(term_map)} terms, {len(fallback_labels)} bravo fallbacks"
    )


async def _assign_images_to_tap_config(
    config_data: Dict[str, Any],
    mascot: str,
    account_id: str,
    aac_user_id: str,
    skip_remaining_lookup: bool = False,
    force_full_lookup: bool = False,
) -> Dict[str, Any]:
    """
    Resolve images for every static pool button in the tap config and save to Firestore.
    Also backfills missing pool buttons for static boards created before the pool feature.

    Returns a stats dict with labels_found, images_resolved, save_ok, backfill_changed.
    Uses config_data only to collect labels; reloads a fresh copy from Firestore
    before saving so concurrent writes (e.g. wizard boards-menu save) are not lost.
    """
    import time as _t
    _t0 = _t.perf_counter()
    def _elapsed(label: str, since=None) -> float:
        ms = round((_t.perf_counter() - (since or _t0)) * 1000)
        logging.info(f"⏱ _assign_images [{account_id}/{aac_user_id}] {label}: {ms}ms")
        return _t.perf_counter()

    logging.info(
        f"_assign_images_to_tap_config: START account={account_id} user={aac_user_id} "
        f"mascot={mascot!r} skip_remaining={skip_remaining_lookup} force_full={force_full_lookup}"
    )
    stats: Dict[str, Any] = {"labels_found": 0, "images_resolved": 0, "save_ok": False, "backfill_changed": False, "error": None}
    try:
        # Load a fresh copy from Firestore so we work with the latest state.
        fresh_config = await load_tap_nav_config(account_id, aac_user_id)
        if not fresh_config:
            fresh_config = config_data
        _t1 = _elapsed("load_fresh_config")

        # Race-condition guard: the background task now runs fast enough that a
        # concurrent wizard save can land between our creation and this read.  If
        # the fresh copy has FEWER boards than the config we were handed at task
        # creation time, the fresh copy is stale/truncated — use the original
        # board list to avoid silently dropping boards (e.g. the Actions board).
        original_boards = config_data.get('boards') if isinstance(config_data.get('boards'), list) else []
        fresh_boards = fresh_config.get('boards') if isinstance(fresh_config.get('boards'), list) else []
        if len(original_boards) > len(fresh_boards):
            logging.warning(
                f"_assign_images_to_tap_config: fresh_config has {len(fresh_boards)} boards "
                f"but config_data has {len(original_boards)}; using config_data boards to avoid "
                f"data loss from a concurrent wizard save for {account_id}/{aac_user_id}"
            )
            fresh_config['boards'] = original_boards

        # --- Backfill missing pool buttons ---
        # Static boards created before the pool feature have no pool_index buttons.
        # Re-populate them now using CATEGORY_STATIC_POOLS so pagination works.
        settings = await load_settings_from_file(account_id, aac_user_id)
        tap_words_rows   = int(settings.get('tapWordsRows',   4) or 4)
        grid_cols        = int(settings.get('gridColumns',    6) or 6)
        tap_dynamic_rows = int(settings.get('tapDynamicRows', 0) or 0)
        static_rows      = max(0, tap_words_rows - tap_dynamic_rows)
        default_action   = 'use_ai' if settings.get('useBravoBuild') else (str(settings.get('defaultButtonAction') or 'do_nothing').strip() or 'do_nothing')

        backfill_changed = False
        for board in (fresh_config.get('boards') or []):
            if not isinstance(board, dict) or board.get('board_type') != 'static':
                continue
            existing = board.get('buttons') or []
            pool_btns = [b for b in existing if isinstance(b, dict) and b.get('pool_index') is not None]
            pool = CATEGORY_STATIC_POOLS.get(_pool_key(str(board.get('prompt_category') or '')), [])
            if not pool:
                pool = CATEGORY_STATIC_POOLS.get(_pool_key(str(board.get('label') or '')), [])
            if not pool:
                continue
            # Skip only if pool buttons already exist AND the count matches the current pool definition.
            # Stale boards created before a pool was resized (e.g. 84-item padded → 36-item) must be replaced.
            if pool_btns and len(pool_btns) == len(pool):
                continue  # already correctly populated
            max_on_page = static_rows * grid_cols
            board['buttons'] = [
                _make_pool_button_entry(idx, word, board['id'], idx >= max_on_page, grid_cols, default_action)
                for idx, word in enumerate(pool)
            ]
            board['dynamic_rows'] = tap_dynamic_rows
            backfill_changed = True

        # Collect labels only for buttons that have no image_url yet.
        # Buttons that already have an image_url are left untouched — re-querying
        # Firestore for thousands of existing images is the main source of the
        # 50-90 second lookup_remaining delay on profiles with many non-pool boards.
        all_labels: List[str] = []
        for board in (fresh_config.get('boards') or []):
            if not isinstance(board, dict):
                continue
            for btn in (board.get('buttons') or []):
                if not isinstance(btn, dict):
                    continue
                lbl = str(btn.get('label') or '').strip()
                if lbl and not btn.get('image_url'):
                    all_labels.append(lbl)

        # Collect boards_menu labels separately so we can apply the static index without
        # running Firestore queries for AI-generated / category-name labels that aren't
        # in the pool.  Running _lookup_images_for_labels on thousands of unique
        # boards_menu labels causes 50-90 second delays.
        menu_labels: List[str] = []
        def _walk_menu_labels(items: list) -> None:
            for item in (items or []):
                if not isinstance(item, dict):
                    continue
                lbl = str(item.get('label') or '').strip()
                if lbl:
                    menu_labels.append(lbl)
                _walk_menu_labels(item.get('children') or [])

        _walk_menu_labels(fresh_config.get('boards_menu') or [])

        stats["labels_found"] = len(all_labels) + len(menu_labels)
        stats["backfill_changed"] = backfill_changed
        _t2 = _elapsed("backfill+collect_labels", _t1)

        logging.info(
            f"_assign_images_to_tap_config [{account_id}/{aac_user_id}] "
            f"boards={len(fresh_config.get('boards') or [])} all_labels={len(all_labels)} "
            f"menu_labels={len(menu_labels)} backfill_changed={backfill_changed}"
        )
        if not all_labels and not menu_labels and not backfill_changed:
            return stats

        label_to_url: Dict[str, str] = {}

        # --- Board button labels (static pool words) ---
        # force_full_lookup=True skips the cached index so every label goes through
        # _lookup_images_for_labels.  Used by build_master_profiles_endpoint to ensure
        # master profiles contain environment-specific URLs from the live aac_images
        # collection rather than dev-generated paths from the static index.
        if not force_full_lookup:
            static_idx = await _ensure_static_image_index(mascot)
            _t3 = _elapsed("ensure_static_index", _t2)
            all_labels_set = set(all_labels)
            label_to_url = {lbl: url for lbl, url in static_idx.items() if lbl in all_labels_set}
        else:
            static_idx = {}
            _t3 = _elapsed("ensure_static_index(skipped)", _t2)
            all_labels_set = set(all_labels)

        remaining_board_labels = [lbl for lbl in all_labels if lbl not in label_to_url]
        if remaining_board_labels and not skip_remaining_lookup:
            extra = await _lookup_images_for_labels(
                remaining_board_labels, mascot, account_id, aac_user_id, source="tap_config"
            )
            label_to_url.update(extra)
        elif remaining_board_labels:
            logging.info(
                f"_assign_images: skipping Firestore lookup for {len(remaining_board_labels)} "
                f"remaining labels (skip_remaining_lookup=True) [{account_id}/{aac_user_id}]"
            )
        _elapsed("lookup_remaining", _t3)
        _sample_url = next(iter(label_to_url.values()), None)
        logging.info(
            f"_assign_images [{account_id}/{aac_user_id}] "
            f"images_resolved={len(label_to_url)}/{len(all_labels)} all_labels "
            f"(backfill_changed={backfill_changed}, "
            f"sample_url={(_sample_url or 'none')[:80]!r})"
        )

        # --- boards_menu labels ---
        # Apply static index only.  Category names / AI-generated labels that miss
        stats["images_resolved"] = len(label_to_url)

        # Write image_url and fix after_selection onto every static pool button
        img_changed = False
        correct_action = default_action  # "ai_build_board" when useBravoBuild, else user preference
        for board in (fresh_config.get('boards') or []):
            if not isinstance(board, dict):
                continue
            for btn in (board.get('buttons') or []):
                if not isinstance(btn, dict):
                    continue
                lbl = str(btn.get('label') or '').strip()
                url = label_to_url.get(lbl)
                if url and btn.get('image_url') != url:
                    btn['image_url'] = url
                    img_changed = True
                # Fix after_selection on static pool buttons when useBravoBuild is on
                if correct_action == 'use_ai' and btn.get('button_type') == 'static':
                    current_sel = btn.get('after_selection')
                    if current_sel in ('do_nothing', 'ai_build_board', None, ''):
                        btn['after_selection'] = 'use_ai'
                        img_changed = True

        # Write image_url onto boards_menu items.
        # Category labels ("Greetings", "Help", etc.) are not pool words so they are
        # not in the static index.  Load the master profile's boards_menu directly and
        # copy image_urls by matching label — no index/cache dependency.
        menu_changed = [False]
        master_menu_map: Dict[str, str] = {}
        try:
            _admin_id = await _get_admin_account_id()
            if _admin_id:
                _master_uid = await _find_master_profile_user_id(_admin_id, mascot)
                if _master_uid:
                    _master_cfg = await load_tap_nav_config(_admin_id, _master_uid)
                    if _master_cfg:
                        def _collect_master_menu(items: list) -> None:
                            for _item in (items or []):
                                if not isinstance(_item, dict):
                                    continue
                                _lbl = str(_item.get('label') or '').strip()
                                _url = str(_item.get('image_url') or '').strip()
                                if _lbl and _url and _lbl not in master_menu_map:
                                    master_menu_map[_lbl] = _url
                                _collect_master_menu(_item.get('children') or [])
                        _collect_master_menu(_master_cfg.get('boards_menu') or [])
                        logging.info(
                            f"_assign_images: loaded {len(master_menu_map)} menu label→url "
                            f"entries from master profile {_master_uid!r} for mascot={mascot!r}"
                        )
        except Exception as _e:
            logging.warning(f"_assign_images: could not load master menu images for {mascot!r}: {_e}")

        def _assign_menu_images(items: list) -> None:
            for item in (items or []):
                if not isinstance(item, dict):
                    continue
                lbl = str(item.get('label') or '').strip()
                if lbl:
                    url = master_menu_map.get(lbl) or label_to_url.get(lbl)
                    if url and item.get('image_url') != url:
                        item['image_url'] = url
                        menu_changed[0] = True
                _assign_menu_images(item.get('children') or [])

        _assign_menu_images(fresh_config.get('boards_menu') or [])

        # Custom images (profile + user uploads) take highest priority — override bravo_images.
        try:
            import re as _re_ci
            def _ci_norm(s: str) -> str:
                return ' '.join(_re_ci.sub(r'[^a-z0-9]+', ' ', str(s or '').strip().lower()).split())
            custom_term_map = await _build_custom_image_term_map(account_id, aac_user_id)
            if custom_term_map:
                for _board in (fresh_config.get('boards') or []):
                    if not isinstance(_board, dict):
                        continue
                    for _btn in (_board.get('buttons') or []):
                        if not isinstance(_btn, dict):
                            continue
                        _lbl_n = _ci_norm(_btn.get('label') or '')
                        if _lbl_n in custom_term_map:
                            _cu = custom_term_map[_lbl_n]
                            if _btn.get('image_url') != _cu:
                                _btn['image_url'] = _cu
                                img_changed = True
                def _apply_custom_menu(items: list) -> None:
                    for _item in (items or []):
                        if not isinstance(_item, dict):
                            continue
                        _lbl_n = _ci_norm(_item.get('label') or '')
                        if _lbl_n in custom_term_map:
                            _cu = custom_term_map[_lbl_n]
                            if _item.get('image_url') != _cu:
                                _item['image_url'] = _cu
                                menu_changed[0] = True
                        _apply_custom_menu(_item.get('children') or [])
                _apply_custom_menu(fresh_config.get('boards_menu') or [])
        except Exception as _e_ci:
            logging.warning(f"Custom image override in _assign_images_to_tap_config failed: {_e_ci}")

        # Rebuild the legacy buttons array from the updated boards_menu so the
        # tap interface (which reads tapConfig.buttons) gets the new image_urls.
        if menu_changed[0]:
            fresh_config['buttons'] = compose_legacy_buttons_from_boards_menu(fresh_config)

        _t_presave = _t.perf_counter()
        if backfill_changed or img_changed or menu_changed[0]:
            save_ok = await save_tap_nav_config(account_id, aac_user_id, fresh_config)
            stats["save_ok"] = bool(save_ok)
            _elapsed("save_tap_nav_config", _t_presave)
            _elapsed("TOTAL", )
            logging.info(
                f"✅ Pool/image assignment complete for {account_id}/{aac_user_id}: "
                f"backfill={backfill_changed} images={len(label_to_url)} save_ok={save_ok}"
            )
        else:
            stats["save_ok"] = True  # nothing to save, not an error

        return stats
    except Exception as e:
        stats["error"] = str(e)
        logging.error(f"_assign_images_to_tap_config failed for {account_id}/{aac_user_id}: {e}", exc_info=True)
        return stats


@app.post("/api/tap-interface/boards/assign-all-images")
async def assign_all_board_images(
    payload: Dict[str, Any],
    current_ids: Annotated[Dict[str, str], Depends(get_current_account_and_user_ids)]
):
    """
    Assign (or re-assign) images to all static pool buttons across all boards.
    Used by the board builder Reassign Images button.
    Accepts optional 'mascot' override; falls back to the user's saved setting.
    """
    aac_user_id = current_ids["aac_user_id"]
    account_id  = current_ids["account_id"]

    try:
        mascot = str(payload.get('mascot') or '').strip().lower()
        if not mascot:
            settings = await load_settings_from_file(account_id, aac_user_id)
            mascot = str(settings.get('mascot') or 'buddy').strip().lower()

        config_data = await load_tap_nav_config(account_id, aac_user_id)
        if not config_data:
            raise HTTPException(status_code=404, detail='Board config not found')

        # Guard against a background task from regenerate_boards still running.
        # Wait up to 90s for it to finish, then run the full lookup ourselves.
        _assign_key = (account_id, aac_user_id)
        waited = 0.0
        while _assign_key in _image_assign_in_flight and waited < 90.0:
            await asyncio.sleep(1.0)
            waited += 1.0
        if waited:
            logging.info(
                f"assign_all_board_images: waited {waited:.0f}s for in-flight task to finish "
                f"[{account_id}/{aac_user_id}]"
            )
            # Reload config so we get the version written by the background task
            config_data = await load_tap_nav_config(account_id, aac_user_id) or config_data

        # Run synchronously so the response confirms completion (full Firestore lookup)
        stats = await _assign_images_to_tap_config(config_data, mascot, account_id, aac_user_id)

        return JSONResponse(content={'success': True, 'mascot': mascot, 'debug': stats})
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"assign_all_board_images failed: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/symbols/batch-search")
async def batch_symbol_search(
    request: Request,
    current_ids: Annotated[Dict[str, str], Depends(get_current_account_and_user_ids)]
):
    """
    Batch symbol search endpoint - searches for multiple terms in a single request.
    Returns a map of term -> best matching image URL.
    Uses parallel Firestore queries for maximum performance.
    """
    try:
        data = await request.json()
        terms = data.get('terms', [])
        locale = str(data.get('locale') or 'en-US').strip().lower()
        locale_base = locale.split('-')[0] if '-' in locale else locale
        mascot = str(data.get('mascot') or '').strip().lower()

        def _normalize_quotes_and_space(v):
            text = str(v or '').strip().lower()
            if not text:
                return ''
            text = (
                text.replace(''', "'")
                .replace(''', "'")
                .replace('`', "'")
                .replace('“', '"')
                .replace('”', '"')
            )
            return ' '.join(text.split())

        def _normalize_term(v):
            """Canonical matcher term: lowercase, normalized quotes, punctuation-insensitive."""
            text = _normalize_quotes_and_space(v)
            if not text:
                return ''
            import re
            text = re.sub(r"[^a-z0-9]+", " ", text)
            return ' '.join(text.split())

        def _allowed_locale_keys():
            keys = {"en", "en-us", locale, locale_base}
            return {k for k in keys if k}

        allowed_locale_keys = _allowed_locale_keys()
        
        logging.info(f"🔍 BATCH SEARCH: Received request with {len(terms) if terms else 0} terms")
        if terms:
            logging.info(f"🔍 BATCH SEARCH: First 5 terms: {terms[:5]}")
        
        if not terms or not isinstance(terms, list):
            logging.warning("🔍 BATCH SEARCH: No terms provided or invalid format")
            return JSONResponse(content={"results": {}})
        
        # Limit batch size to prevent abuse
        terms = terms[:50]
        
        aac_user_id = current_ids["aac_user_id"]
        account_id = current_ids["account_id"]

        logging.info(f"🔍 BATCH SEARCH: User ID: {aac_user_id}, Account ID: {account_id}")

        normalize_search_term = None
        if locale_base and locale_base != "en":
            try:
                from aac_inflection_utils import normalize_search_term as _normalize_search_term
                normalize_search_term = _normalize_search_term
            except Exception as inflection_import_error:
                logging.debug(f"🔍 BATCH: inflection module unavailable: {inflection_import_error}")

        def _chunked(values, size=10):
            values_list = list(values)
            for i in range(0, len(values_list), size):
                chunk = values_list[i:i + size]
                if chunk:
                    yield chunk

        TOKEN_STOP_WORDS = {
            'the', 'a', 'an', 'and', 'or', 'to', 'of', 'on', 'in', 'at', 'for', 'with',
            'if', 'you', 'your', 'are', 'is', 'it', 're', 's'
        }

        def _expand_terms(text_value, keywords_value):
            query_raw = str(text_value or '').strip()
            query_lower = _normalize_quotes_and_space(query_raw)
            normalized_query = query_lower
            if normalize_search_term and query_lower:
                try:
                    inflection_normalized = _normalize_quotes_and_space(normalize_search_term(query_lower, locale_base))
                    if inflection_normalized:
                        normalized_query = inflection_normalized
                except Exception as inflection_error:
                    logging.debug(f"🔍 BATCH: inflection normalization skipped for '{query_lower}': {inflection_error}")

            query_norm = _normalize_term(query_lower)
            normalized_query_norm = _normalize_term(normalized_query)

            out = []
            if query_lower:
                out.append(query_lower)
                if normalized_query and normalized_query != query_lower:
                    out.append(normalized_query)
                if query_norm and query_norm not in out:
                    out.append(query_norm)
                if normalized_query_norm and normalized_query_norm not in out:
                    out.append(normalized_query_norm)
                for part in query_lower.split():
                    part = part.strip().lower()
                    if len(part) >= 3 and part not in TOKEN_STOP_WORDS:
                        out.append(part)
                for part in query_norm.split():
                    part = part.strip().lower()
                    if len(part) >= 3 and part not in TOKEN_STOP_WORDS:
                        out.append(part)

            for kw in (keywords_value or [])[:3]:
                kw_lower = _normalize_quotes_and_space(kw)
                kw_norm = _normalize_term(kw)
                if not kw_lower and not kw_norm:
                    continue
                if kw_lower:
                    out.append(kw_lower)
                if kw_norm:
                    out.append(kw_norm)
                for part in kw_norm.split():
                    part = part.strip().lower()
                    if len(part) >= 3 and part not in TOKEN_STOP_WORDS:
                        out.append(part)

            deduped = []
            seen = set()
            for term in out:
                if term and term not in seen:
                    seen.add(term)
                    deduped.append(term)
            return query_lower, normalized_query, deduped[:10]

        request_items = []
        all_search_terms = set()
        for item in terms:
            if isinstance(item, dict):
                text = str(item.get('text', '')).strip()
                keywords = item.get('keywords', [])
            else:
                text = str(item).strip()
                keywords = []

            if not text:
                continue

            query_lower, normalized_query, search_terms = _expand_terms(text, keywords)
            if not search_terms and query_lower:
                search_terms = [query_lower]

            request_items.append({
                "text": text,
                "query_lower": query_lower,
                "normalized_query": normalized_query,
                "search_terms": search_terms,
            })
            for term in search_terms:
                if term:
                    all_search_terms.add(term)

        if not request_items:
            return JSONResponse(content={"results": {}})

        def _batch_cache_key(item_rec):
            # Scope cache per account/profile/locale/mascot and search-term set.
            # Mascot is part of the key so that changing mascot returns mascot-appropriate images.
            terms_sig = "|".join(item_rec.get("search_terms", []))
            return f"v3:{account_id}:{aac_user_id}:{locale_base}:{mascot}:{item_rec.get('query_lower', '')}:{terms_sig}"

        # --- Serve cached results without hitting Firestore ---
        now_ts = time.time()
        cached_results = {}
        uncached_items = []
        for item_rec in request_items:
            cache_key = _batch_cache_key(item_rec)
            cached_entry = _batch_search_cache.get(cache_key)
            if cached_entry and cached_entry[1] > now_ts:
                cached_results[item_rec["text"]] = cached_entry[0]
            else:
                uncached_items.append(item_rec)

        if not uncached_items:
            logging.info(f"🔍 BATCH SEARCH: All {len(request_items)} terms served from cache (no Firestore)")
            return JSONResponse(content={"results": cached_results})

        # Narrow Firestore search to only the terms we don't have cached yet
        all_search_terms = set()
        for item_rec in uncached_items:
            for term in item_rec["search_terms"]:
                if term:
                    all_search_terms.add(term)

        # Collect all unique exact search terms from uncached items globally
        all_exact_terms = set()
        for item_rec in uncached_items:
            query_lower = item_rec.get("query_lower", "")
            normalized_term = item_rec.get("normalized_query", "")
            raw_text = str(item_rec.get("text", "")).strip()

            exact_terms = [raw_text, query_lower, normalized_term]
            if raw_text:
                exact_terms.extend([
                    raw_text.lower(),
                    raw_text.capitalize(),
                    raw_text.title(),
                    _normalize_quotes_and_space(raw_text),
                    _normalize_term(raw_text),
                ])
            for t in exact_terms:
                tt = str(t or '').strip()
                if tt:
                    all_exact_terms.add(tt)

        images_ref = firestore_db.collection("aac_images")
        candidate_docs = {}

        # Build list of queries to run in parallel
        queries = []
        
        # 1. Grouped query path 1: precomputed normalized search terms
        for chunk in _chunked(all_search_terms, 10):
            queries.append(("path1", images_ref.where("search_terms", "array_contains_any", chunk).limit(300)))
            
        # 2. Per-item exact term fetches using batch 'in' operator to query concept and subconcept in parallel
        for chunk in _chunked(all_exact_terms, 10):
            queries.append(("exact_subconcept", images_ref.where("source", "==", "bravo_images").where("subconcept", "in", chunk).limit(100)))
            queries.append(("exact_concept", images_ref.where("source", "==", "bravo_images").where("concept", "in", chunk).limit(100)))
            if locale_base and locale_base != "en":
                localized_labels_field = f"localized_labels.{locale_base}"
                queries.append(("exact_localized_labels", images_ref.where("source", "==", "bravo_images").where(localized_labels_field, "in", chunk).limit(100)))

        # 3. Grouped query path 2: localized tags fallback
        if locale_base and locale_base != "en":
            localized_tags_field = f"localized_tags.{locale_base}"
            for chunk in _chunked(all_search_terms, 10):
                queries.append(("localized_tags", images_ref.where("source", "==", "bravo_images").where(localized_tags_field, "array_contains_any", chunk).limit(250)))

        # 4. Grouped query path 3: legacy tags fallback
        for chunk in _chunked(all_search_terms, 10):
            queries.append(("legacy_tags", images_ref.where("source", "==", "bravo_images").where("tags", "array_contains_any", chunk).limit(250)))

        # Helper to execute query stream block in thread pool
        def _execute_query_stream(query):
            return list(query.stream())

        # Execute all queries in parallel
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = None

        if loop and loop.is_running():
            tasks = [asyncio.to_thread(_execute_query_stream, q) for q_type, q in queries]
            results = await asyncio.gather(*tasks, return_exceptions=True)
        else:
            results = [_execute_query_stream(q) for q_type, q in queries]

        # Process results
        for (q_type, q), result in zip(queries, results):
            if isinstance(result, Exception):
                logging.warning(f"🔍 BATCH: Query {q_type} failed with error: {result}")
                continue
            
            for doc in result:
                data = doc.to_dict() or {}
                if not data.get("image_url"):
                    continue
                
                # Path 1 check: legacy code requires source == "bravo_images"
                if q_type == "path1":
                    if data.get("source") == "bravo_images":
                        candidate_docs[doc.id] = data
                else:
                    candidate_docs[doc.id] = data

        def _extract_localized_terms_for_doc(doc_data):
            localized_terms = []
            localized_tags_raw = doc_data.get('localized_tags')
            localized_labels_raw = doc_data.get('localized_labels')

            if isinstance(localized_tags_raw, dict):
                for locale_key, locale_tags in localized_tags_raw.items():
                    locale_key_norm = _normalize_term(locale_key)
                    if locale_key_norm not in allowed_locale_keys:
                        continue
                    if isinstance(locale_tags, list):
                        localized_terms.extend([_normalize_term(tag) for tag in locale_tags if _normalize_term(tag)])

            if isinstance(localized_labels_raw, dict):
                for locale_key, locale_label in localized_labels_raw.items():
                    locale_key_norm = _normalize_term(locale_key)
                    if locale_key_norm not in allowed_locale_keys:
                        continue
                    label_norm = _normalize_term(locale_label)
                    if label_norm:
                        localized_terms.append(label_norm)

            return localized_terms

        processed_candidates = []
        term_index = {}
        for image_id, image in candidate_docs.items():
            tags = [_normalize_term(t) for t in image.get('tags', []) if _normalize_term(t)]
            concept = _normalize_term(image.get('concept'))
            subconcept = _normalize_term(image.get('subconcept'))
            localized_terms = _extract_localized_terms_for_doc(image)
            searchable_terms = set([*tags, concept, subconcept, *localized_terms])

            record = {
                "id": image_id,
                "url": image.get("image_url"),
                "tags": tags,
                "concept": concept,
                "subconcept": subconcept,
                "searchable_terms": searchable_terms,
                "mascot": _normalize_term(image.get("mascot") or "") or None,
            }
            processed_candidates.append(record)

            for term in searchable_terms:
                if not term:
                    continue
                if term not in term_index:
                    term_index[term] = set()
                term_index[term].add(image_id)

        candidate_by_id = {c["id"]: c for c in processed_candidates}

        # Load active custom images once, then score in-memory as fallback.
        custom_candidates = []
        custom_term_index = {}
        try:
            custom_ref = firestore_db.collection("accounts").document(account_id).collection("profiles").document(aac_user_id).collection("custom_images")
            custom_docs = list(custom_ref.where("active", "==", True).limit(500).stream())
            for doc in custom_docs:
                custom_image = doc.to_dict() or {}
                image_url = custom_image.get('image_url')
                if not image_url:
                    continue

                tags = [_normalize_term(t) for t in custom_image.get('tags', []) if _normalize_term(t)]
                concept = _normalize_term(custom_image.get('concept'))
                subconcept = _normalize_term(custom_image.get('subconcept'))
                aliases = [_normalize_term(a) for a in custom_image.get('aliases', []) if _normalize_term(a)]
                localized_terms = _extract_localized_terms_for_doc(custom_image)
                searchable_terms = set([*tags, *aliases, concept, subconcept, *localized_terms])

                rec = {
                    "id": doc.id,
                    "url": image_url,
                    "tags": tags,
                    "concept": concept,
                    "subconcept": subconcept,
                    "searchable_terms": searchable_terms,
                    "mascot": str(custom_image.get('mascot') or '').strip().lower(),
                    "source": "custom_images",
                }
                custom_candidates.append(rec)
                for term in searchable_terms:
                    if not term:
                        continue
                    if term not in custom_term_index:
                        custom_term_index[term] = set()
                    custom_term_index[term].add(doc.id)
        except Exception as custom_load_error:
            logging.debug(f"🔍 BATCH: failed to preload custom images ({custom_load_error})")

        custom_by_id = {c["id"]: c for c in custom_candidates}

        def _score_candidate(item_rec, cand):
            """
            Priority order (strict):
            1) Exact subconcept match
            2) Exact concept match
            3) Tag/alias/localized term matches
            This prevents tag-only hits (e.g. "queen" tagged "red")
            from outranking true subconcept matches for "red".
            """
            score = 0
            query_lower = item_rec["query_lower"]
            normalized_query = item_rec["normalized_query"]
            search_terms = item_rec["search_terms"]

            query_norm = _normalize_term(normalized_query or query_lower)

            subconcept = cand.get("subconcept") or ""
            concept = cand.get("concept") or ""
            searchable_terms = cand.get("searchable_terms") or set()
            tags = cand.get("tags") or []

            exact_subconcept = bool(
                (query_norm and query_norm == subconcept)
                or (normalized_query and _normalize_term(normalized_query) == subconcept)
                or (query_lower and _normalize_term(query_lower) == subconcept)
            )
            exact_concept = bool(
                (query_norm and query_norm == concept)
                or (normalized_query and _normalize_term(normalized_query) == concept)
                or (query_lower and _normalize_term(query_lower) == concept)
            )

            # Large tiered bases to guarantee ordering.
            if exact_subconcept:
                score += 1000
            elif exact_concept:
                score += 900

            # Strongly prefer candidates that contain the full normalized phrase
            # in any searchable field (tags, aliases, localized labels/tags, concept, subconcept).
            if query_norm and query_norm in searchable_terms:
                score += 780

            for idx, term in enumerate(search_terms):
                if term in searchable_terms:
                    # Keep generic searchable-term points below concept tiers.
                    score += max(8, 24 - (idx * 2))
                if tags and tags[0] == term:
                    score += 6

            # Mascot scoring: strongly prefer matching mascot, penalize wrong mascot.
            if mascot:
                img_mascot = cand.get("mascot") or ""
                if img_mascot == mascot:
                    score += 500
                elif img_mascot and img_mascot != mascot:
                    score -= 400

            # Mild source preference: custom images win close ties.
            if cand.get("source") == "custom_images":
                score += 4

            return score

        results = {**cached_results}  # start with cache hits
        expires_at = time.time() + _BATCH_SEARCH_CACHE_TTL
        for item_rec in uncached_items:
            text = item_rec["text"]

            candidate_ids = set()
            custom_ids = set()
            for term in item_rec["search_terms"]:
                candidate_ids.update(term_index.get(term, set()))
                custom_ids.update(custom_term_index.get(term, set()))

            best_url = None
            best_score = -1
            for candidate_id in candidate_ids:
                cand = candidate_by_id.get(candidate_id)
                if not cand:
                    continue
                score = _score_candidate(item_rec, cand)
                if score > best_score:
                    best_score = score
                    best_url = cand["url"]

            # Evaluate custom candidates in the same competition (not fallback-only).
            for custom_id in custom_ids:
                cand = custom_by_id.get(custom_id)
                if not cand:
                    continue
                score = _score_candidate(item_rec, cand)
                if score > best_score:
                    best_score = score
                    best_url = cand["url"]

            results[text] = best_url
            # Store in TTL cache (None results too, to avoid repeated Firestore misses)
            _batch_search_cache[_batch_cache_key(item_rec)] = (best_url, expires_at)

        # Evict stale entries periodically to prevent unbounded memory growth
        if len(_batch_search_cache) > 2000:
            now_ts2 = time.time()
            stale_keys = [k for k, v in _batch_search_cache.items() if v[1] <= now_ts2]
            for k in stale_keys:
                del _batch_search_cache[k]
        
        logging.info(f"🔍 BATCH SEARCH: Completed - {len(results)} results ({len(cached_results)} from cache, {len(uncached_items)} from Firestore)")
        logging.info(f"🔍 BATCH SEARCH: Results summary: {list(results.keys())[:10]}")
        return JSONResponse(content={"results": results})
        
    except Exception as e:
        logging.error(f"Error in batch symbol search: {e}")
        return JSONResponse(
            status_code=500,
            content={"error": "Batch search failed", "details": str(e)}
        )


@app.get("/api/symbols/library-download")
async def download_image_library(
    current_ids: Annotated[Dict[str, str], Depends(get_current_account_and_user_ids)]
):
    """
    Download entire AAC image library for local caching.
    Returns all aac_images with source="bravo_images" for client-side search.
    This enables instant local tag-based search without network calls.
    """
    try:
        logging.info("📚 LIBRARY DOWNLOAD: Starting full library download")
        
        # Query all bravo images
        images_ref = firestore_db.collection('aac_images')
        query = images_ref.where('source', '==', 'bravo_images')
        docs = query.stream()

        def _flatten_search_terms(value):
            if isinstance(value, (str, int, float)):
                text = str(value).strip()
                return [text] if text else []
            if isinstance(value, list):
                output = []
                for item in value:
                    output.extend(_flatten_search_terms(item))
                return output
            if isinstance(value, dict):
                output = []
                for item in value.values():
                    output.extend(_flatten_search_terms(item))
                return output
            return []
        
        library = []
        for doc in docs:
            data = doc.to_dict()
            localized_tags = data.get('localized_tags', {})
            localized_labels = data.get('localized_labels', {})
            aliases = data.get('aliases', [])

            search_terms = []
            search_terms.extend(_flatten_search_terms(data.get('concept')))
            search_terms.extend(_flatten_search_terms(data.get('subconcept')))
            search_terms.extend(_flatten_search_terms(data.get('tags', [])))
            search_terms.extend(_flatten_search_terms(aliases))
            search_terms.extend(_flatten_search_terms(localized_tags))
            search_terms.extend(_flatten_search_terms(localized_labels))

            search_terms = [str(term).strip().lower() for term in search_terms if str(term).strip()]
            search_terms = list(dict.fromkeys(search_terms))

            # Only include essential fields to minimize download size
            library.append({
                'id': doc.id,
                'image_url': data.get('image_url'),
                'concept': data.get('concept'),
                'subconcept': data.get('subconcept'),
                'tags': data.get('tags', []),
                'aliases': aliases,
                'localized_tags': localized_tags,
                'localized_labels': localized_labels,
                'search_terms': search_terms,
                'source': data.get('source'),
                'mascot': data.get('mascot'),
                # Include any other metadata that might be useful for search
                'category': data.get('category'),
                'subcategory': data.get('subcategory')
            })
        
        logging.info(f"📚 LIBRARY DOWNLOAD: Sending {len(library)} images to client")
        
        return JSONResponse(content={
            "images": library,
            "count": len(library),
            "timestamp": datetime.now().isoformat()
        })
        
    except Exception as e:
        logging.error(f"Error downloading image library: {e}")
        return JSONResponse(
            status_code=500,
            content={"error": "Library download failed", "details": str(e)}
        )


